CREATE OR REPLACE FUNCTION public.on_hms_incident_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _actor uuid;
  _title text;
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    _actor := COALESCE(auth.uid(), NEW.assigned_to);

    INSERT INTO public.hms_incident_status_log (incident_id, company_id, from_status, to_status, reason, changed_by)
    VALUES (NEW.id, NEW.company_id, OLD.status, NEW.status, NEW.closed_reason, _actor);

    -- Notify reporter (if different from actor)
    IF NEW.reported_by IS NOT NULL AND NEW.reported_by <> COALESCE(_actor, '00000000-0000-0000-0000-000000000000'::uuid) THEN
      _title := CASE
        WHEN NEW.status = 'closed' THEN 'HMS-avvik lukket'
        WHEN NEW.status = 'rejected' THEN 'HMS-avvik avvist'
        WHEN NEW.status = 'in_progress' THEN 'HMS-avvik under behandling'
        WHEN NEW.status = 'action_pending' THEN 'Tiltak opprettet på HMS-avvik'
        ELSE 'HMS-avvik status oppdatert'
      END;

      INSERT INTO public.notifications (
        user_id, company_id, type, title, message, priority,
        entity_type, entity_id, link_url, actor_user_id
      ) VALUES (
        NEW.reported_by, NEW.company_id, 'hms.incident.status_changed',
        _title, COALESCE(NEW.title, 'HMS-avvik'),
        'info', 'hms_incident', NEW.id,
        '/hms/incidents/' || NEW.id::text, _actor
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_order_message_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _submission record;
  _title text;
  _body text;
  _link text;
  _sender_label text;
  _snippet text;
  _user_id uuid;
  _notified uuid[] := ARRAY[]::uuid[];
BEGIN
  -- Only customer / external-originated messages trigger internal notifications
  IF NEW.sender_type IS NULL OR NEW.sender_type NOT IN ('customer', 'external', 'bestiller') THEN
    RETURN NEW;
  END IF;

  SELECT id, submission_no, company_id, assigned_to, submitted_by,
         COALESCE(submitter_name, notification_recipient_name, 'Bestiller') AS who
    INTO _submission
    FROM order_form_submissions
   WHERE id = NEW.submission_id;

  IF _submission IS NULL THEN
    RETURN NEW;
  END IF;

  _sender_label := COALESCE(NULLIF(NEW.sender_name, ''), _submission.who, 'Bestiller');
  _snippet := LEFT(regexp_replace(COALESCE(NEW.body, ''), E'\\s+', ' ', 'g'), 140);
  _title := 'Ny melding på bestilling ' || COALESCE(_submission.submission_no, '#');
  _body := _sender_label || COALESCE(': ' || NULLIF(_snippet, ''), '');
  _link := '/orders/' || _submission.id::text;

  -- Assignee
  IF _submission.assigned_to IS NOT NULL THEN
    _notified := array_append(_notified, _submission.assigned_to);
  END IF;
  -- Submitter (if internal)
  IF _submission.submitted_by IS NOT NULL THEN
    _notified := array_append(_notified, _submission.submitted_by);
  END IF;
  -- Internal participants with receives_notifications
  FOR _user_id IN
    SELECT DISTINCT ofp.user_id
      FROM order_form_participants ofp
     WHERE ofp.submission_id = NEW.submission_id
       AND ofp.participant_type = 'internal_user'
       AND ofp.user_id IS NOT NULL
       AND ofp.is_active
       AND ofp.receives_notifications
  LOOP
    _notified := array_append(_notified, _user_id);
  END LOOP;

  -- Fallback: company admins if no recipient found
  IF array_length(_notified, 1) IS NULL THEN
    FOR _user_id IN SELECT public._notif_admin_user_ids() LOOP
      _notified := array_append(_notified, _user_id);
    END LOOP;
  END IF;

  -- Dedup + insert, skip the sender themselves
  FOR _user_id IN SELECT DISTINCT unnest(_notified) LOOP
    IF NEW.sender_user_id IS NOT NULL AND _user_id = NEW.sender_user_id THEN
      CONTINUE;
    END IF;
    BEGIN
      INSERT INTO notifications
        (user_id, company_id, type, priority, title, message, link_url,
         entity_type, entity_id, actor_name)
      VALUES
        (_user_id, _submission.company_id, 'order_message', 'important',
         _title, _body, _link, 'order_message', NEW.id, _sender_label);
    EXCEPTION WHEN OTHERS THEN
      BEGIN
        INSERT INTO order_form_activity_log (submission_id, event_type, payload)
        VALUES (NEW.submission_id, 'notification_failed', jsonb_build_object(
          'notification_type', 'customer_message',
          'message_id', NEW.id,
          'user_id', _user_id,
          'error', SQLERRM,
          'sqlstate', SQLSTATE
        ));
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END;
  END LOOP;

  BEGIN
    INSERT INTO order_form_activity_log (submission_id, event_type, payload)
    VALUES (NEW.submission_id, 'customer_message_received',
      jsonb_build_object(
        'message_id', NEW.id,
        'sender_type', NEW.sender_type,
        'sender_name', NEW.sender_name,
        'snippet', _snippet,
        'notified_user_ids', to_jsonb(_notified)
      ));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.backfill_commercial_cases_for_active()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _from_leads int := 0;
  _from_calc_cases int := 0;
  _from_calculations int := 0;
  _from_events int := 0;
  _new_id uuid;
  r record;
BEGIN
  -- Leads som er åpne (ikke vunnet/tapt/konvertert) og uten sak
  FOR r IN
    SELECT l.id, l.company_id, COALESCE(l.title, l.subject, 'Lead') AS title,
           l.customer_id, l.contact_person_id, l.created_by
    FROM public.leads l
    WHERE l.commercial_case_id IS NULL
      AND COALESCE(l.deleted_at, NULL) IS NULL
      AND COALESCE(l.status, 'open') NOT IN ('won','lost','converted','closed')
  LOOP
    INSERT INTO public.commercial_cases (company_id, title, customer_id, contact_person_id, created_by, source, phase)
    VALUES (r.company_id, r.title, r.customer_id, r.contact_person_id, r.created_by, 'lead', 'lead')
    RETURNING id INTO _new_id;
    UPDATE public.leads SET commercial_case_id = _new_id WHERE id = r.id;
    _from_leads := _from_leads + 1;
  END LOOP;

  -- Kalkylesaker (calc_cases) som er aktive og uten sak
  FOR r IN
    SELECT cc.id, cc.company_id, COALESCE(cc.title, 'Kalkylesak') AS title, cc.created_by
    FROM public.calc_cases cc
    WHERE cc.commercial_case_id IS NULL
      AND cc.deleted_at IS NULL
  LOOP
    INSERT INTO public.commercial_cases (company_id, title, created_by, source, phase)
    VALUES (r.company_id, r.title, r.created_by, 'calc', 'calculating')
    RETURNING id INTO _new_id;
    UPDATE public.calc_cases SET commercial_case_id = _new_id WHERE id = r.id;
    _from_calc_cases := _from_calc_cases + 1;
  END LOOP;

  -- Frittstående kalkyler/tilbud (uten calc_case og uten commercial_case)
  FOR r IN
    SELECT c.id, c.company_id, COALESCE(c.project_title, 'Kalkyle/Tilbud') AS title,
           c.created_by, c.total_price
    FROM public.calculations c
    WHERE c.commercial_case_id IS NULL
      AND c.deleted_at IS NULL
      AND c.case_id IS NULL
  LOOP
    INSERT INTO public.commercial_cases (company_id, title, created_by, source, phase, value_estimate)
    VALUES (r.company_id, r.title, r.created_by, 'calc', 'calculating', r.total_price)
    RETURNING id INTO _new_id;
    UPDATE public.calculations SET commercial_case_id = _new_id WHERE id = r.id;
    _from_calculations := _from_calculations + 1;
  END LOOP;

  -- Aktive prosjekter (events) som ikke er ferdige/avlyst og uten sak
  FOR r IN
    SELECT e.id, e.company_id, COALESCE(e.title, 'Prosjekt') AS title, e.created_by
    FROM public.events e
    WHERE e.commercial_case_id IS NULL
      AND e.deleted_at IS NULL
      AND COALESCE(e.status, 'planned') NOT IN ('completed','cancelled','archived')
      AND COALESCE(e.project_type, 'project') = 'project'
  LOOP
    INSERT INTO public.commercial_cases (company_id, title, created_by, source, phase, won_at)
    VALUES (r.company_id, r.title, r.created_by, 'project', 'won', now())
    RETURNING id INTO _new_id;
    UPDATE public.events SET commercial_case_id = _new_id WHERE id = r.id;
    _from_events := _from_events + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'from_leads', _from_leads,
    'from_calc_cases', _from_calc_cases,
    'from_calculations', _from_calculations,
    'from_events', _from_events,
    'ran_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_order_status_to_linked_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _case_id uuid;
  _new_case_status text;
  _resolution text;
BEGIN
  -- Only fire on status changes
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- Find linked case (either via linked_case_id on the order, or via linked_order_submission_id on cases)
  _case_id := NEW.linked_case_id;

  IF _case_id IS NULL THEN
    SELECT id INTO _case_id FROM public.cases
    WHERE linked_order_submission_id = NEW.id
      AND deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF _case_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Map order status to case status
  _resolution := NULL;
  CASE NEW.status
    WHEN 'new' THEN
      _new_case_status := 'in_progress';
    WHEN 'under_review' THEN
      _new_case_status := 'in_progress';
    WHEN 'missing_info' THEN
      _new_case_status := 'waiting_customer';
    WHEN 'waiting_customer' THEN
      _new_case_status := 'waiting_customer';
    WHEN 'waiting_internal' THEN
      _new_case_status := 'waiting_internal';
    WHEN 'ready_for_planning' THEN
      _new_case_status := 'converted';
      _resolution := 'converted_to_order';
    WHEN 'task_created' THEN
      _new_case_status := 'converted';
      _resolution := 'converted_to_order';
    WHEN 'in_progress' THEN
      _new_case_status := 'converted';
      _resolution := 'converted_to_order';
    WHEN 'closed' THEN
      _new_case_status := 'closed';
      _resolution := 'converted_to_order';
    WHEN 'rejected' THEN
      _new_case_status := 'closed';
      _resolution := 'converted_to_order';
    ELSE
      RETURN NEW;
  END CASE;

  -- Update the case
  UPDATE public.cases
  SET status = _new_case_status::case_status,
      resolution_type = COALESCE(_resolution, resolution_type),
      updated_at = now()
  WHERE id = _case_id
    AND deleted_at IS NULL;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_task_thread_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _thread record;
  _recipient record;
  _notif_type text;
  _priority text;
  _title text;
  _body text;
  _link text;
  _msg_priority text;
BEGIN
  IF NEW.message_type = 'system_event' THEN
    RETURN NEW;
  END IF;

  SELECT tt.task_id, e.title AS task_title, e.company_id AS event_company_id
  INTO _thread
  FROM task_threads tt
  JOIN events e ON e.id = tt.task_id
  WHERE tt.id = NEW.thread_id;

  IF _thread IS NULL THEN
    RETURN NEW;
  END IF;

  _msg_priority := COALESCE(NEW.priority, 'normal');

  IF NEW.message_type = 'external_email' AND NEW.direction = 'inbound' THEN
    _notif_type := 'task_thread_inbound_email';
    _priority := CASE 
      WHEN _msg_priority = 'urgent' THEN 'critical'
      WHEN _msg_priority = 'important' THEN 'important'
      ELSE 'important'
    END;
    _title := 'Nytt e-postsvar på: ' || COALESCE(_thread.task_title, 'Oppgave');
    _body := LEFT(COALESCE(NEW.body, ''), 200);
  ELSIF NEW.message_type = 'internal_message' THEN
    _notif_type := 'task_thread_message';
    _priority := CASE 
      WHEN _msg_priority = 'urgent' THEN 'critical'
      WHEN _msg_priority = 'important' THEN 'important'
      ELSE 'info'
    END;
    _title := CASE
      WHEN _msg_priority = 'urgent' THEN '🔴 HASTER: ' || COALESCE(_thread.task_title, 'Oppgave')
      WHEN _msg_priority = 'important' THEN '⚠️ Viktig: ' || COALESCE(_thread.task_title, 'Oppgave')
      ELSE 'Ny melding på: ' || COALESCE(_thread.task_title, 'Oppgave')
    END;
    _body := LEFT(COALESCE(NEW.body, ''), 200);
  ELSIF NEW.message_type = 'external_email' AND NEW.direction = 'outbound' THEN
    _notif_type := 'task_thread_message';
    _priority := CASE 
      WHEN _msg_priority = 'urgent' THEN 'critical'
      WHEN _msg_priority = 'important' THEN 'important'
      ELSE 'info'
    END;
    _title := CASE
      WHEN _msg_priority = 'urgent' THEN '🔴 HASTER: ' || COALESCE(_thread.task_title, 'Oppgave')
      WHEN _msg_priority = 'important' THEN '⚠️ Viktig: ' || COALESCE(_thread.task_title, 'Oppgave')
      ELSE 'Ny melding på: ' || COALESCE(_thread.task_title, 'Oppgave')
    END;
    _body := LEFT(COALESCE(NEW.body, ''), 200);
  ELSE
    RETURN NEW;
  END IF;

  _link := '/projects/plan?openTask=' || _thread.task_id::text;

  FOR _recipient IN
    SELECT DISTINCT t.user_id
    FROM event_technicians et
    JOIN technicians t ON t.id = et.technician_id
    WHERE et.event_id = _thread.task_id
      AND t.user_id IS NOT NULL
      AND t.user_id != COALESCE(NEW.author_user_id, '00000000-0000-0000-0000-000000000000'::uuid)
  LOOP
    INSERT INTO notifications (user_id, company_id, type, priority, title, message, link_url, entity_type, entity_id, actor_user_id, actor_name)
    VALUES (_recipient.user_id, _thread.event_company_id, _notif_type, _priority, _title, _body, _link, 'task_thread', _thread.task_id, NEW.author_user_id, NEW.author_name)
    ON CONFLICT DO NOTHING;
  END LOOP;

  FOR _recipient IN
    SELECT DISTINCT jp.user_id
    FROM job_participants jp
    WHERE jp.job_id = _thread.task_id
      AND jp.user_id IS NOT NULL
      AND jp.user_id != COALESCE(NEW.author_user_id, '00000000-0000-0000-0000-000000000000'::uuid)
  LOOP
    INSERT INTO notifications (user_id, company_id, type, priority, title, message, link_url, entity_type, entity_id, actor_user_id, actor_name)
    VALUES (_recipient.user_id, _thread.event_company_id, _notif_type, _priority, _title, _body, _link, 'task_thread', _thread.task_id, NEW.author_user_id, NEW.author_name)
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_work_visit_from_plan(p_event_id uuid DEFAULT NULL::uuid, p_technician_id uuid DEFAULT NULL::uuid, p_remove_all boolean DEFAULT false, p_schedule_block_id uuid DEFAULT NULL::uuid, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _event_id uuid := p_event_id;
  _event record;
  _target record;
  _targets integer := 0;
  _blocks integer := 0;
  _step integer := 0;
  _assignments integer := 0;
  _approvals integer := 0;
  _links integer := 0;
  _remaining integer := 0;
  _event_cancelled boolean := false;
  _already_removed boolean := false;
  _candidate_ids jsonb;
BEGIN
  IF _event_id IS NULL AND p_schedule_block_id IS NOT NULL THEN
    SELECT COALESCE(CASE WHEN je.project_type = 'task' THEN je.id END, CASE WHEN pe.project_type = 'task' THEN pe.id END, sb.job_id, sb.project_id)
    INTO _event_id
    FROM public.schedule_blocks sb
    LEFT JOIN public.events je ON je.id = sb.job_id
    LEFT JOIN public.events pe ON pe.id = sb.project_id
    WHERE sb.id = p_schedule_block_id;
  END IF;
  IF _event_id IS NULL THEN RAISE EXCEPTION 'event_not_found'; END IF;
  SELECT * INTO _event FROM public.events WHERE id = _event_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'event_not_found'; END IF;

  IF NOT p_remove_all AND p_technician_id IS NULL AND p_schedule_block_id IS NOT NULL THEN
    SELECT technician_id INTO p_technician_id FROM public.schedule_blocks WHERE id = p_schedule_block_id;
  END IF;
  IF NOT p_remove_all AND p_technician_id IS NULL THEN RAISE EXCEPTION 'technician_required'; END IF;

  CREATE TEMP TABLE IF NOT EXISTS _remove_targets (
    technician_id uuid PRIMARY KEY, event_technician_id uuid, technician_user_id uuid,
    technician_name text, mailbox text, calendar_event_id text, start_at timestamptz, end_at timestamptz
  ) ON COMMIT DROP;
  TRUNCATE _remove_targets;

  INSERT INTO _remove_targets
  SELECT t.id, et.id, t.user_id, t.name, t.email, et.calendar_event_id,
         COALESCE(et.start_at, _event.start_time), COALESCE(et.end_at, _event.end_time)
  FROM public.event_technicians et JOIN public.technicians t ON t.id = et.technician_id
  WHERE et.event_id = _event_id AND (p_remove_all OR et.technician_id = p_technician_id)
  ON CONFLICT (technician_id) DO NOTHING;

  INSERT INTO _remove_targets (technician_id, technician_user_id, technician_name, mailbox, calendar_event_id, start_at, end_at)
  SELECT t.id, t.user_id, t.name, t.email,
         (array_agg(COALESCE(sb.outlook_event_id, jcl.calendar_event_id) ORDER BY sb.start_at) FILTER (WHERE COALESCE(sb.outlook_event_id, jcl.calendar_event_id) IS NOT NULL))[1],
         min(sb.start_at), max(sb.end_at)
  FROM public.schedule_blocks sb
  JOIN public.technicians t ON t.id = sb.technician_id
  LEFT JOIN public.job_calendar_links jcl ON jcl.job_id = _event_id AND jcl.technician_id = sb.technician_id AND jcl.provider = 'microsoft'
  WHERE (sb.job_id = _event_id OR sb.project_id = _event_id)
    AND (p_remove_all OR sb.technician_id = p_technician_id)
  GROUP BY t.id, t.user_id, t.name, t.email
  ON CONFLICT (technician_id) DO UPDATE SET
    technician_user_id = COALESCE(_remove_targets.technician_user_id, EXCLUDED.technician_user_id), technician_name = COALESCE(_remove_targets.technician_name, EXCLUDED.technician_name),
    mailbox = COALESCE(_remove_targets.mailbox, EXCLUDED.mailbox), calendar_event_id = COALESCE(_remove_targets.calendar_event_id, EXCLUDED.calendar_event_id),
    start_at = LEAST(_remove_targets.start_at, EXCLUDED.start_at), end_at = GREATEST(_remove_targets.end_at, EXCLUDED.end_at);

  IF NOT p_remove_all AND NOT EXISTS (SELECT 1 FROM _remove_targets) THEN
    INSERT INTO _remove_targets (technician_id, technician_user_id, technician_name, mailbox, start_at, end_at)
    SELECT id, user_id, name, email, _event.start_time, _event.end_time FROM public.technicians WHERE id = p_technician_id
    ON CONFLICT DO NOTHING;
  END IF;

  SELECT count(*) INTO _targets FROM _remove_targets;
  _already_removed := NOT EXISTS (SELECT 1 FROM public.event_technicians et JOIN _remove_targets rt ON rt.technician_id=et.technician_id WHERE et.event_id=_event_id)
    AND NOT EXISTS (SELECT 1 FROM public.schedule_blocks sb JOIN _remove_targets rt ON rt.technician_id=sb.technician_id WHERE (sb.job_id=_event_id OR sb.project_id=_event_id) AND sb.deleted_at IS NULL);

  FOR _target IN SELECT * FROM _remove_targets LOOP
    SELECT COALESCE(jsonb_agg(DISTINCT x.event_id) FILTER (WHERE x.event_id IS NOT NULL), '[]'::jsonb) INTO _candidate_ids
    FROM (
      SELECT _target.calendar_event_id event_id
      UNION ALL SELECT outlook_event_id FROM public.schedule_blocks WHERE (job_id=_event_id OR project_id=_event_id) AND technician_id=_target.technician_id
      UNION ALL SELECT calendar_event_id FROM public.job_calendar_links WHERE job_id=_event_id AND technician_id=_target.technician_id AND provider='microsoft'
      UNION ALL SELECT outlook_event_id FROM public.job_approvals WHERE job_id=_event_id AND technician_user_id=_target.technician_user_id
    ) x;
    INSERT INTO public.calendar_delete_retry_queue (event_id,technician_id,event_technician_id,technician_user_id,technician_name,mailbox,candidate_event_ids,start_at,end_at,status,next_attempt_at,resolved_at,last_error)
    VALUES (_event_id,_target.technician_id,_target.event_technician_id,_target.technician_user_id,_target.technician_name,_target.mailbox,_candidate_ids,_target.start_at,_target.end_at,'pending',now(),NULL,NULL)
    ON CONFLICT (event_id,technician_id) DO UPDATE SET
      event_technician_id=COALESCE(EXCLUDED.event_technician_id,calendar_delete_retry_queue.event_technician_id), technician_user_id=COALESCE(EXCLUDED.technician_user_id,calendar_delete_retry_queue.technician_user_id),
      technician_name=COALESCE(EXCLUDED.technician_name,calendar_delete_retry_queue.technician_name), mailbox=COALESCE(EXCLUDED.mailbox,calendar_delete_retry_queue.mailbox),
      candidate_event_ids=CASE WHEN jsonb_array_length(EXCLUDED.candidate_event_ids)>0 THEN EXCLUDED.candidate_event_ids ELSE calendar_delete_retry_queue.candidate_event_ids END,
      start_at=COALESCE(EXCLUDED.start_at,calendar_delete_retry_queue.start_at), end_at=COALESCE(EXCLUDED.end_at,calendar_delete_retry_queue.end_at),
      status=CASE WHEN calendar_delete_retry_queue.status='resolved' THEN 'resolved' ELSE 'pending' END, next_attempt_at=now(),
      last_error=CASE WHEN calendar_delete_retry_queue.status='resolved' THEN calendar_delete_retry_queue.last_error ELSE NULL END;
  END LOOP;

  UPDATE public.schedule_blocks sb SET deleted_at=COALESCE(sb.deleted_at,now()), deleted_reason=COALESCE(sb.deleted_reason,CASE WHEN p_remove_all THEN 'work_visit_removed' ELSE 'technician_unplanned' END), updated_at=now()
  FROM _remove_targets rt WHERE (sb.job_id=_event_id OR sb.project_id=_event_id) AND sb.technician_id=rt.technician_id AND sb.deleted_at IS NULL;
  GET DIAGNOSTICS _blocks=ROW_COUNT;

  DELETE FROM public.job_approvals ja USING _remove_targets rt WHERE ja.job_id=_event_id AND rt.technician_user_id IS NOT NULL AND ja.technician_user_id=rt.technician_user_id;
  GET DIAGNOSTICS _approvals=ROW_COUNT;
  UPDATE public.job_calendar_links jcl SET sync_status='unlinked', updated_at=now() FROM _remove_targets rt WHERE jcl.job_id=_event_id AND jcl.technician_id=rt.technician_id AND jcl.provider='microsoft';
  GET DIAGNOSTICS _links=ROW_COUNT;
  DELETE FROM public.event_technicians et USING _remove_targets rt WHERE et.event_id=_event_id AND et.technician_id=rt.technician_id;
  GET DIAGNOSTICS _assignments=[REDACTED]  SELECT count(*) INTO _remaining FROM public.event_technicians WHERE event_id=_event_id;

  IF _remaining=0 AND (_event.project_type='task' OR p_remove_all) THEN
    UPDATE public.schedule_blocks SET deleted_at=COALESCE(deleted_at,now()),deleted_reason=COALESCE(deleted_reason,'work_visit_cancelled'),updated_at=now()
    WHERE (job_id=_event_id OR project_id=_event_id) AND deleted_at IS NULL;
    GET DIAGNOSTICS _step=ROW_COUNT; _blocks:=_blocks+_step;
    UPDATE public.events SET status='cancelled',deleted_at=COALESCE(deleted_at,now()),deleted_by=COALESCE(deleted_by,p_actor),cancelled_at=COALESCE(cancelled_at,now()),cancelled_by=COALESCE(cancelled_by,p_actor),outlook_sync_status='delete_pending',updated_at=now(),updated_by=COALESCE(p_actor,updated_by) WHERE id=_event_id;
    _event_cancelled:=true;
  ELSIF _remaining=0 THEN
    UPDATE public.events SET status='requested',outlook_sync_status='delete_pending',updated_at=now(),updated_by=COALESCE(p_actor,updated_by) WHERE id=_event_id;
  ELSE
    UPDATE public.events SET outlook_sync_status='delete_pending',updated_at=now(),updated_by=COALESCE(p_actor,updated_by) WHERE id=_event_id;
  END IF;

  INSERT INTO public.event_logs(event_id,action_type,performed_by,change_summary) VALUES (_event_id,CASE WHEN _event_cancelled THEN 'work_visit_unplanned' ELSE 'technician_unplanned' END,p_actor,CASE WHEN _event_cancelled THEN 'Arbeidsbesøk avplanlagt; siste eller alle montører fjernet' ELSE format('%s montør(er) fjernet fra arbeidsbesøket',_assignments) END);
  INSERT INTO public.activity_log(entity_type,entity_id,action,type,description,performed_by,metadata) VALUES ('event',_event_id,'work_visit_unplanned','system','Samlet avplanlegging utført; Outlook-sletting lagt i synkroniseringskø',p_actor,jsonb_build_object('remove_all',p_remove_all,'technician_id',p_technician_id,'schedule_blocks',_blocks,'assignments',_assignments,'approvals',_approvals,'calendar_links',_links,'remaining_assignments',_remaining,'event_cancelled',_event_cancelled));

  RETURN jsonb_build_object('status',CASE WHEN _already_removed AND _blocks=0 AND _assignments=[REDACTED] AND _approvals=0 THEN 'already_removed' ELSE 'success' END,'event_id',_event_id,'targets',_targets,'schedule_blocks_removed',_blocks,'assignments_removed',_assignments,'approvals_removed',_approvals,'calendar_links_unlinked',_links,'remaining_assignments',_remaining,'event_cancelled',_event_cancelled);
END; $function$

CREATE OR REPLACE FUNCTION public.repair_resource_plan_ghosts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _blocks int:=0; _assignments int:=0; _approvals int:=0; _links int:=0;
BEGIN
 UPDATE public.schedule_blocks sb SET deleted_at=now(),deleted_reason='ghost_repair',updated_at=now() WHERE sb.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.events e WHERE e.id=COALESCE(sb.job_id,sb.project_id) AND (e.deleted_at IS NOT NULL OR e.status='cancelled')); GET DIAGNOSTICS _blocks=ROW_COUNT;
 DELETE FROM public.job_approvals ja WHERE NOT EXISTS(SELECT 1 FROM public.events e WHERE e.id=ja.job_id AND e.deleted_at IS NULL AND e.status<>'cancelled'); GET DIAGNOSTICS _approvals=ROW_COUNT;
 UPDATE public.job_calendar_links jcl SET sync_status='unlinked',updated_at=now(),last_error=COALESCE(last_error,'Ghost booking repair: Outlook delete required') WHERE jcl.sync_status='linked' AND NOT EXISTS(SELECT 1 FROM public.events e WHERE e.id=jcl.job_id AND e.deleted_at IS NULL AND e.status<>'cancelled'); GET DIAGNOSTICS _links=ROW_COUNT;
 DELETE FROM public.event_technicians et WHERE NOT EXISTS(SELECT 1 FROM public.events e WHERE e.id=et.event_id AND e.deleted_at IS NULL AND e.status<>'cancelled'); GET DIAGNOSTICS _assignments=[REDACTED] RETURN jsonb_build_object('schedule_blocks_repaired',_blocks,'assignments_repaired',_assignments,'approvals_repaired',_approvals,'calendar_links_repaired',_links,'repaired_at',now());
END; $function$

CREATE OR REPLACE FUNCTION public.assess_person_requirement(_company_id uuid, _person_id uuid, _requirement_id uuid, _reason text, _valid_until date DEFAULT NULL::date, _revoke_id uuid DEFAULT NULL::uuid, _client_request_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE req public.compliance_competence_requirements; previous public.compliance_requirement_assessments; existing public.compliance_requirement_assessments; context jsonb; actor_name text; result uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_company_access(auth.uid(),_company_id,'hms','edit') THEN RAISE EXCEPTION 'Ingen tilgang til HMS-endring i selskapet' USING ERRCODE='42501'; END IF;
 IF nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Begrunnelse er påkrevd'; END IF;
 IF _client_request_id IS NULL THEN RAISE EXCEPTION 'Forespørsels-ID er påkrevd'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_company_id::text || _person_id::text || _requirement_id::text,0));
 SELECT * INTO existing FROM public.compliance_requirement_assessments WHERE client_request_id=_client_request_id;
 IF FOUND THEN
  IF existing.company_id<>_company_id OR existing.person_id<>_person_id OR existing.requirement_id<>_requirement_id OR existing.assessed_by<>auth.uid() OR existing.reason<>trim(_reason) OR existing.valid_until IS DISTINCT FROM _valid_until OR existing.revoked_assessment_id IS DISTINCT FROM _revoke_id THEN RAISE EXCEPTION 'Forespørsels-ID er allerede brukt'; END IF;
  RETURN existing.id;
 END IF;
 SELECT * INTO req FROM public.compliance_competence_requirements WHERE id=_requirement_id AND company_id=_company_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kravet finnes ikke i selskapet'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',ep.id,'department_id',ep.department_id,'job_role_id',ep.job_role_id) ORDER BY ep.id),'[]'::jsonb) INTO context FROM public.employment_profiles ep JOIN public.people p ON p.id=ep.person_id WHERE ep.company_id=_company_id AND ep.person_id=_person_id AND ep.archived_at IS NULL AND ep.include_in_hms_people AND p.is_active IS NOT FALSE;
 IF context='[]'::jsonb THEN RAISE EXCEPTION 'Personen er ikke aktiv i selskapets HMS-grunnlag'; END IF;
 IF _revoke_id IS NULL THEN
  IF _valid_until IS NOT NULL AND _valid_until < CURRENT_DATE THEN RAISE EXCEPTION 'Revurderingsdato kan ikke være passert'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.compliance_effective_requirements(_company_id,_person_id) e WHERE e.requirement_id=_requirement_id AND e.required) THEN RAISE EXCEPTION 'Kravet er ikke et gjeldende påkrevd personkrav'; END IF;
  IF EXISTS (SELECT 1 FROM public.compliance_active_requirement_assessment(_company_id,_person_id,_requirement_id)) THEN RAISE EXCEPTION 'Opphev eksisterende vurdering før en ny registreres'; END IF;
 ELSE
  SELECT * INTO previous FROM public.compliance_requirement_assessments WHERE id=_revoke_id AND company_id=_company_id AND person_id=_person_id AND requirement_id=_requirement_id AND decision='not_relevant';
  IF NOT FOUND THEN RAISE EXCEPTION 'Vurderingen finnes ikke på dette personkravet'; END IF;
  IF EXISTS (SELECT 1 FROM public.compliance_requirement_assessments WHERE revoked_assessment_id=_revoke_id) THEN RAISE EXCEPTION 'Vurderingen er allerede opphevet'; END IF;
 END IF;
 SELECT p.full_name INTO actor_name FROM public.user_accounts ua JOIN public.people p ON p.id=ua.person_id WHERE ua.auth_user_id=auth.uid() AND ua.is_active LIMIT 1;
 INSERT INTO public.compliance_requirement_assessments(company_id,person_id,requirement_id,competence_type_id,decision,reason,assessed_by,assessor_name,valid_until,requirement_updated_at,employment_context,revoked_assessment_id,client_request_id)
 VALUES (_company_id,_person_id,_requirement_id,req.competence_type_id,CASE WHEN _revoke_id IS NULL THEN 'not_relevant' ELSE 'revoke' END,trim(_reason),auth.uid(),COALESCE(actor_name,'HMS-ansvarlig'),CASE WHEN _revoke_id IS NULL THEN _valid_until ELSE NULL END,req.updated_at,context,_revoke_id,_client_request_id) RETURNING id INTO result;
 RETURN result;
END; $function$

CREATE OR REPLACE FUNCTION public.notify_order_message_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _participant record;
  _submission record;
  _title text;
  _body text;
  _link text;
  _supabase_url text;
  _service_key text;
BEGIN
  -- Only fire for messages with an addressed participant
  IF NEW.addressed_to_participant_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Look up participant
  SELECT ofp.user_id, ofp.name, ofp.participant_type, ofp.receives_notifications
  INTO _participant
  FROM order_form_participants ofp
  WHERE ofp.id = NEW.addressed_to_participant_id;

  -- Only notify internal users with a user_id
  IF _participant IS NULL OR _participant.user_id IS NULL OR _participant.participant_type != 'internal_user' THEN
    RETURN NEW;
  END IF;

  -- Don't notify yourself
  IF _participant.user_id = NEW.sender_user_id THEN
    RETURN NEW;
  END IF;

  -- Look up submission for context
  SELECT ofs.id, ofs.submission_no, ofs.company_id,
         COALESCE(ofs.summary, '') AS summary
  INTO _submission
  FROM order_form_submissions ofs
  WHERE ofs.id = NEW.submission_id;

  IF _submission IS NULL THEN
    RETURN NEW;
  END IF;

  _title := 'Melding til deg på bestilling ' || COALESCE(_submission.submission_no, '#');
  _body := LEFT(COALESCE(NEW.body, ''), 200);
  _link := '/orders/' || _submission.id::text;

  -- Create in-app notification
  INSERT INTO notifications (
    user_id, company_id, type, priority, title, message, link_url,
    entity_type, entity_id, actor_user_id, actor_name
  ) VALUES (
    _participant.user_id,
    _submission.company_id,
    'order_message_addressed',
    'important',
    _title,
    _body,
    _link,
    'order_form_submission',
    _submission.id,
    NEW.sender_user_id,
    NEW.sender_name
  );

  -- Trigger email send via pg_net (fire-and-forget to edge function)
  IF _participant.receives_notifications THEN
    _supabase_url := current_setting('app.settings.supabase_url', true);
    _service_key := current_setting('app.settings.service_role_key', true);

    BEGIN
      PERFORM net.http_post(
        COALESCE(_supabase_url, 'https://nmqycanqumelmfpdmkpr.supabase.co') || '/functions/v1/order-message-email-send',
        jsonb_build_object('message_id', NEW.id),
        jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || COALESCE(_service_key, current_setting('supabase.service_role_key', true))
        )
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Could not trigger order email: %', SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_submission_summary(_submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _result jsonb := '{}'::jsonb;
  _existing jsonb;
  _site text;
  _street text;
  _postal text;
  _city text;
  _firma text;
  _kunde text;
  _bestiller text;
  _kontakt text;
  r record;
  _val text;
  _label text;
  _fk text;
BEGIN
  SELECT COALESCE(s.summary, '{}'::jsonb) INTO _existing
  FROM public.order_form_submissions s WHERE s.id = _submission_id;

  FOR r IN
    SELECT v.field_key, v.value, COALESCE(f.label, '') AS label
    FROM public.order_form_submission_values v
    LEFT JOIN public.order_form_submissions s ON s.id = v.submission_id
    LEFT JOIN public.order_form_template_fields f
      ON f.template_id = s.template_id AND f.field_key = v.field_key
    WHERE v.submission_id = _submission_id
  LOOP
    IF jsonb_typeof(r.value) = 'string' THEN
      _val := trim(r.value #>> '{}');
    ELSIF jsonb_typeof(r.value) IN ('number','boolean') THEN
      _val := r.value #>> '{}';
    ELSE
      _val := NULL;
    END IF;
    IF _val IS NULL OR _val = '' THEN CONTINUE; END IF;

    _label := lower(trim(r.label));
    _fk := lower(r.field_key);

    IF _site IS NULL AND (
      _label IN ('oppdragssted','lokasjon','arbeidssted','anlegg','anleggsnavn',
                 'prosjekt','prosjektnavn','project','project name','site','site name',
                 'facility','facility name','customer site','job site')
    ) THEN
      _site := _val;
    ELSIF _street IS NULL AND (
      _label IN ('adresse','addresse','gateadresse','oppdragsadresse','anleggsadresse',
                 'street','street address','address','address line','address line 1',
                 'job address','site address')
      OR _fk LIKE 'anleggsadresse%' OR _fk LIKE 'gateadresse%'
    ) AND _val !~ '^\d{4}\s' THEN
      _street := _val;
    ELSIF (_postal IS NULL OR _city IS NULL) AND _val ~ '^\d{4}\s' THEN
      _postal := substring(_val from '^(\d{4})');
      _city := trim(substring(_val from '^\d{4}\s+(.*)$'));
    ELSIF _postal IS NULL AND _label IN ('postnummer','postcode','postal code','zip','zip code') THEN
      _postal := _val;
    ELSIF _city IS NULL AND _label IN ('poststed','postal city','city','sted') THEN
      _city := _val;
    ELSIF _firma IS NULL AND (
      _label IN ('firmanavn','firma','company','company name','fakturamottaker')
      OR _fk LIKE 'firmanavn%' OR _fk LIKE 'fakturamottaker%'
    ) THEN
      _firma := _val;
    ELSIF _kunde IS NULL AND _label IN ('kundenavn','kunde','customer','customer name') THEN
      _kunde := _val;
    ELSIF _kontakt IS NULL AND (
      _label IN ('kontaktperson','kontaktperson kunde','contact','contact name')
      OR _fk LIKE 'kontaktperson%'
    ) THEN
      _kontakt := _val;
    ELSIF _bestiller IS NULL AND (
      _label IN ('bestiller','bestiller – navn','bestiller navn','bestiller-navn')
      OR _fk LIKE 'bestiller_navn%'
    ) THEN
      _bestiller := _val;
    END IF;
  END LOOP;

  RETURN _existing || jsonb_strip_nulls(jsonb_build_object(
    'oppdragssted', _site,
    'adresse', _street,
    'postnummer', _postal,
    'poststed', _city,
    'firmanavn', _firma,
    'kundenavn', _kunde,
    'kontaktperson_kunde', _kontakt,
    'bestiller_navn', _bestiller
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.create_work_visits_on_project_batch(p_root_id uuid, p_dates date[], p_start_time time without time zone, p_end_time time without time zone, p_technician_ids uuid[], p_title text DEFAULT NULL::text, p_overnight boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _parent RECORD;
  _root_id uuid := p_root_id;
  _user uuid := auth.uid();
  _results jsonb := '[]'::jsonb;
  _date date;
  _start timestamptz;
  _end timestamptz;
  _tech uuid;
  _event_id uuid;
  _existing_id uuid;
  _status text;
  _inserted_blocks int;
  _existing_block uuid;
  _err_msg text; _err_state text; _err_detail text; _err_hint text;
BEGIN
  SELECT id, company_id, title, project_type, description, address, created_by
    INTO _parent
    FROM public.events
    WHERE id = _root_id AND deleted_at IS NULL;

  IF _parent.id IS NULL THEN
    RAISE EXCEPTION 'Parent project % not found', _root_id;
  END IF;

  FOREACH _date IN ARRAY p_dates LOOP
    BEGIN
      _status := NULL;
      _inserted_blocks := 0;
      _start := (_date::text || ' ' || p_start_time::text)::timestamptz;
      IF p_overnight OR p_end_time <= p_start_time THEN
        _end := ((_date + 1)::text || ' ' || p_end_time::text)::timestamptz;
      ELSE
        _end := (_date::text || ' ' || p_end_time::text)::timestamptz;
      END IF;

      SELECT id INTO _existing_id
        FROM public.events
        WHERE parent_event_id = _root_id
          AND deleted_at IS NULL
          AND start_time = _start
          AND end_time = _end
        LIMIT 1;

      IF _existing_id IS NOT NULL THEN
        _event_id := _existing_id;
        _status := 'existing';
      ELSE
        INSERT INTO public.events (
          title, company_id, project_type, description, address,
          start_time, end_time, status, created_by, parent_event_id
        ) VALUES (
          COALESCE(NULLIF(p_title,''), _parent.title),
          _parent.company_id, _parent.project_type, _parent.description, _parent.address,
          _start, _end, 'scheduled', _user, _root_id
        ) RETURNING id INTO _event_id;
        _status := 'created';
      END IF;

      IF p_technician_ids IS NOT NULL THEN
        FOREACH _tech IN ARRAY p_technician_ids LOOP
          INSERT INTO public.event_technicians (event_id, technician_id)
          VALUES (_event_id, _tech)
          ON CONFLICT DO NOTHING;

          SELECT id INTO _existing_block
            FROM public.schedule_blocks
            WHERE technician_id = _tech
              AND project_id = _event_id
              AND start_at = _start
              AND end_at = _end
              AND deleted_at IS NULL
            LIMIT 1;

          IF _existing_block IS NULL THEN
            INSERT INTO public.schedule_blocks (
              company_id, technician_id, project_id, parent_project_id, source, start_at, end_at,
              title, match_state, match_confidence, match_reason
            ) VALUES (
              _parent.company_id, _tech, _root_id, _event_id, 'manual', _start, _end,
              COALESCE(NULLIF(p_title,''), _parent.title),
              'manual', 100, 'Arbeidsbesøk via planlegger'
            );
            _inserted_blocks := _inserted_blocks + 1;
          END IF;
        END LOOP;
      END IF;

      IF _status = 'existing' AND _inserted_blocks > 0 THEN
        _status := 'repaired';
      END IF;

      -- Defensive log insert: never block work-visit creation on log write.
      BEGIN
        INSERT INTO public.event_logs (event_id, action_type, performed_by, change_summary, metadata)
        VALUES (_event_id, 'work_visit_' || _status, _user,
                CASE WHEN _status='created' THEN 'Arbeidsbesøk opprettet'
                     WHEN _status='repaired' THEN 'Arbeidsbesøk reparert (manglende planblokker)'
                     ELSE 'Arbeidsbesøk fantes fra før' END,
                jsonb_build_object('inserted_blocks', _inserted_blocks, 'root_id', _root_id, 'date', _date,
                                   'start', _start, 'end', _end,
                                   'overnight', (_start::date <> _end::date)));
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'event_logs insert failed for event % action_type work_visit_%: %',
          _event_id, _status, SQLERRM;
      END;

      _results := _results || jsonb_build_object(
        'date', _date,
        'event_id', _event_id,
        'status', _status,
        'inserted_blocks', _inserted_blocks,
        'overnight', (_start::date <> _end::date)
      );
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        _err_msg = MESSAGE_TEXT,
        _err_state = RETURNED_SQLSTATE,
        _err_detail = PG_EXCEPTION_DETAIL,
        _err_hint = PG_EXCEPTION_HINT;

      RAISE WARNING 'create_work_visits_on_project_batch failed for date % (sqlstate %): % | detail: % | hint: %',
        _date, _err_state, _err_msg, _err_detail, _err_hint;

      _results := _results || jsonb_build_object(
        'date', _date,
        'error', _err_msg,
        'sqlstate', _err_state
      );
    END;
  END LOOP;

  RETURN jsonb_build_object('results', _results);
END;
$function$

CREATE OR REPLACE FUNCTION public.planning_validate_company_choices()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); co uuid; dept uuid; inv uuid;
BEGIN
  IF uid IS NULL THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'planning_projects' THEN
    co := NEW.company_id; dept := NEW.department_id; inv := NEW.invoicing_company_id;
    IF co IS NOT NULL AND (TG_OP = 'INSERT' OR co IS DISTINCT FROM OLD.company_id) AND NOT public.can_plan_for_company(uid, co) THEN
      RAISE EXCEPTION 'Du har ikke planleggingstilgang til valgt ansvarlig firma';
    END IF;
    IF inv IS NOT NULL AND (TG_OP = 'INSERT' OR inv IS DISTINCT FROM OLD.invoicing_company_id) AND NOT public.can_plan_for_company(uid, inv) THEN
      RAISE EXCEPTION 'Du har ikke planleggingstilgang til valgt fakturerende firma';
    END IF;
  ELSE
    co := NEW.responsible_company_id; dept := NEW.responsible_department_id; inv := NEW.billing_from_company_id;
    IF co IS NOT NULL AND (TG_OP = 'INSERT' OR co IS DISTINCT FROM OLD.responsible_company_id) AND NOT public.can_plan_for_company(uid, co) THEN
      RAISE EXCEPTION 'Du har ikke planleggingstilgang til valgt ansvarlig firma';
    END IF;
    IF inv IS NOT NULL AND (TG_OP = 'INSERT' OR inv IS DISTINCT FROM OLD.billing_from_company_id) AND NOT public.can_plan_for_company(uid, inv) THEN
      RAISE EXCEPTION 'Du har ikke planleggingstilgang til valgt fakturerende firma';
    END IF;
  END IF;
  IF dept IS NOT NULL AND co IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.departments d WHERE d.id = dept AND d.company_id = co) THEN
    RAISE EXCEPTION 'Valgt avdeling tilhører ikke valgt firma';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.create_work_visit_on_project(p_parent_id uuid, p_client_request_id uuid, p_title text, p_start timestamp with time zone, p_end timestamp with time zone, p_technician_ids uuid[], p_extra jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user uuid := auth.uid();
  _parent record;
  _root_id uuid;
  _event_id uuid;
  _status text := 'created';
  _existing record;
  _tech uuid;
  _inserted_blocks int := 0;
BEGIN
  IF p_parent_id IS NULL OR p_client_request_id IS NULL OR p_start IS NULL OR p_end IS NULL THEN
    RAISE EXCEPTION 'missing required parameters';
  END IF;

  -- Resolve true root project (walk up if parent itself is a task)
  SELECT id, parent_project_id, project_type, company_id, title, customer, address, postal_code, city,
         location_details, site_contact_name, site_contact_phone, access_notes, map_link, description,
         customer_practical_info, source_order_form_id
    INTO _parent FROM public.events WHERE id = p_parent_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'parent project not found'; END IF;

  _root_id := CASE WHEN _parent.project_type = 'task' AND _parent.parent_project_id IS NOT NULL
                   THEN _parent.parent_project_id ELSE _parent.id END;

  -- Reload from root if changed
  IF _root_id <> _parent.id THEN
    SELECT id, parent_project_id, project_type, company_id, title, customer, address, postal_code, city,
           location_details, site_contact_name, site_contact_phone, access_notes, map_link, description,
           customer_practical_info, source_order_form_id
      INTO _parent FROM public.events WHERE id = _root_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'root project not found'; END IF;
  END IF;

  -- Idempotency: look up existing event by client_request_id
  SELECT id INTO _existing FROM public.events
   WHERE client_request_id = p_client_request_id AND deleted_at IS NULL LIMIT 1;

  IF FOUND THEN
    _event_id := _existing.id;
    _status := 'existing';
  ELSE
    INSERT INTO public.events (
      parent_project_id, project_type, title, customer, address, postal_code, city,
      location_details, site_contact_name, site_contact_phone, access_notes, map_link,
      description, customer_practical_info, start_time, end_time, technician_id, status,
      created_by, client_request_id, company_id, source_order_form_id
    ) VALUES (
      _root_id, 'task',
      COALESCE(NULLIF(p_title,''), _parent.title),
      _parent.customer, _parent.address, _parent.postal_code, _parent.city,
      _parent.location_details, _parent.site_contact_name, _parent.site_contact_phone,
      _parent.access_notes, _parent.map_link, _parent.description, _parent.customer_practical_info,
      p_start, p_end,
      COALESCE(p_technician_ids[1], _user),
      'requested', _user, p_client_request_id, _parent.company_id, _parent.source_order_form_id
    ) RETURNING id INTO _event_id;
  END IF;

  -- Upsert event_technicians (idempotent)
  IF p_technician_ids IS NOT NULL THEN
    FOREACH _tech IN ARRAY p_technician_ids LOOP
      INSERT INTO public.event_technicians (event_id, technician_id, start_at, end_at)
      VALUES (_event_id, _tech, p_start, p_end)
      ON CONFLICT (event_id, technician_id) DO UPDATE
        SET start_at = EXCLUDED.start_at, end_at = EXCLUDED.end_at;
    END LOOP;

    -- Insert missing schedule_blocks (idempotent by tech+start+end+job)
    FOREACH _tech IN ARRAY p_technician_ids LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.schedule_blocks sb
        WHERE sb.job_id = _event_id AND sb.technician_id = _tech
          AND sb.start_at = p_start AND sb.end_at = p_end AND sb.deleted_at IS NULL
      ) THEN
        INSERT INTO public.schedule_blocks (
          company_id, technician_id, project_id, job_id, source, start_at, end_at,
          title, match_state, match_confidence, match_reason
        ) VALUES (
          _parent.company_id, _tech, _root_id, _event_id, 'manual', p_start, p_end,
          COALESCE(NULLIF(p_title,''), _parent.title),
          'manual', 100, 'Arbeidsbesøk via planlegger'
        );
        _inserted_blocks := _inserted_blocks + 1;
      END IF;
    END LOOP;
  END IF;

  -- Event log
  INSERT INTO public.event_logs (event_id, action_type, performed_by, change_summary, metadata)
  VALUES (_event_id, 'work_visit_' || _status, _user,
          CASE WHEN _status='existing' THEN 'Arbeidsbesøk fantes fra før, fullført' ELSE 'Arbeidsbesøk opprettet' END,
          jsonb_build_object('inserted_blocks', _inserted_blocks, 'root_id', _root_id));

  IF _status = 'existing' AND _inserted_blocks > 0 THEN
    _status := 'repaired';
  END IF;

  RETURN jsonb_build_object(
    'event_id', _event_id,
    'root_project_id', _root_id,
    'status', _status,
    'inserted_blocks', _inserted_blocks
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.planning_members_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record;
BEGIN
  IF NEW.member_type = 'internal' AND NEW.user_id IS NOT NULL AND auth.uid() IS NOT NULL THEN
    SELECT * INTO m FROM public.planning_eligible_participants() e
      WHERE e.user_id = NEW.user_id
      ORDER BY (e.company_id = NEW.company_id) DESC NULLS LAST LIMIT 1;
    IF m.user_id IS NULL THEN
      RAISE EXCEPTION 'Du kan ikke legge til denne personen som deltaker' USING ERRCODE = '42501';
    END IF;
    NEW.company_id := COALESCE(NEW.company_id, m.company_id);
    NEW.department_id := COALESCE(NEW.department_id, m.department_id);
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_by := COALESCE(auth.uid(), NEW.created_by);
    NEW.created_at := now();
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.planning_external_open_project(_token text, _project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 DECLARE person uuid; e public.planning_external_participants; s public.planning_external_portal_sessions; t text; BEGIN
person:=public.planning_external_portal_person(_token); IF person IS NULL OR _project_id IS NULL THEN RAISE EXCEPTION 'Prosjektet eksisterer ikke lenger, eller tilgangen er avsluttet.' USING ERRCODE='42501'; END IF;
SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.external_person_id=person AND ep.planning_project_id=_project_id AND ep.status='active' AND ep.deleted_at IS NULL AND public.planning_external_mode_for(p.status,p.deleted_at,p.completed_at)<>'none';
IF e.id IS NULL THEN RAISE EXCEPTION 'Prosjektet eksisterer ikke lenger, eller tilgangen er avsluttet.' USING ERRCODE='42501'; END IF;
SELECT * INTO s FROM public.planning_external_portal_sessions WHERE token_hash=[REDACTED]'sha256'),'hex') AND expires_at>now();
t:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.planning_external_sessions(participant_id,token_hash,expires_at,portal_session_id) VALUES(e.id,encode(extensions.digest(t,'sha256'),'hex'),least(s.expires_at,now()+interval '1 hour'),s.id);
RETURN jsonb_build_object('session_token',t); END $function$

CREATE OR REPLACE FUNCTION public.planning_external_accept_login(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 DECLARE l public.planning_external_login_links; e public.planning_external_participants; t text; BEGIN
SELECT * INTO l FROM public.planning_external_login_links WHERE token_hash=[REDACTED]'sha256'),'hex') AND length(_token)>=40 AND used_at IS NULL AND expires_at>now() FOR UPDATE;
SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.id=l.participant_id AND ep.status IN ('active','pending','sent','send_failed') AND ep.deleted_at IS NULL AND public.planning_external_mode_for(p.status,p.deleted_at,p.completed_at)<>'none' FOR UPDATE OF ep;
IF l.id IS NULL OR e.id IS NULL THEN RAISE EXCEPTION 'Lenken er utløpt eller brukt, eller tilgangen er avsluttet. Be om en ny tilgangslenke.' USING ERRCODE='42501'; END IF;
UPDATE public.planning_external_login_links SET used_at=now() WHERE id=l.id;
UPDATE public.planning_external_participants SET status='active',accepted_at=coalesce(accepted_at,now()),invite_hash=NULL WHERE id=e.id;
t:=public.planning_external_portal_mint(e.external_person_id);
RETURN jsonb_build_object('portal_token',t,'project_id',e.planning_project_id); END $function$

CREATE OR REPLACE FUNCTION public.create_material_suggestion(p_token uuid, p_name text, p_email text, p_elnr text, p_description text, p_quantity numeric, p_unit text, p_provided_by text, p_comment text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_list_id uuid;
  v_id uuid;
BEGIN
  SELECT id INTO v_list_id FROM public.material_lists WHERE share_token = p_token LIMIT 1;
  IF v_list_id IS NULL THEN
    RAISE EXCEPTION 'Ugyldig delingslenke';
  END IF;

  IF COALESCE(p_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Antall må være større enn 0';
  END IF;

  IF (COALESCE(p_elnr, '') = '' AND COALESCE(p_description, '') = '') THEN
    RAISE EXCEPTION 'Enten elnr eller beskrivelse må fylles ut';
  END IF;

  INSERT INTO public.material_external_suggestions(
    material_list_id, share_token, suggested_by_name, suggested_by_email,
    elnr, description, quantity, unit, provided_by, comment, status
  ) VALUES (
    v_list_id, p_token, NULLIF(p_name, ''), NULLIF(p_email, ''),
    NULLIF(p_elnr, ''), NULLIF(p_description, ''),
    p_quantity, COALESCE(NULLIF(p_unit, ''), 'stk'),
    NULLIF(p_provided_by, ''), NULLIF(p_comment, ''), 'pending'
  ) RETURNING id INTO v_id;

  -- Loggfør
  INSERT INTO public.material_activity_log(material_list_id, actor_id, actor_name, actor_type, event_type, message, metadata)
  VALUES (
    v_list_id, NULL, COALESCE(NULLIF(p_name, ''), 'Bestiller'), 'external',
    'suggestion_created',
    'Bestiller foreslo materiell: ' || COALESCE(NULLIF(p_description, ''), NULLIF(p_elnr, ''), '—'),
    jsonb_build_object('suggestion_id', v_id)
  );

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.hms_handbook_ack_internal(p_version_id uuid, p_section_id uuid DEFAULT NULL::uuid, p_user_agent text DEFAULT NULL::text, p_confirmation_text text DEFAULT 'Jeg har lest og forstått.'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ver public.hms_handbook_versions;
  v_person uuid;
  v_recipient uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('error', 'unauthenticated'); END IF;
  SELECT * INTO ver FROM public.hms_handbook_versions WHERE id = p_version_id;
  IF ver.id IS NULL THEN RETURN jsonb_build_object('error', 'not_found'); END IF;
  IF NOT public.is_company_member(auth.uid(), ver.company_id) THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;

  SELECT ua.person_id INTO v_person
  FROM public.user_accounts ua
  WHERE ua.auth_user_id = auth.uid() AND ua.company_id = ver.company_id
  LIMIT 1;

  SELECT r.id INTO v_recipient
  FROM public.hms_handbook_recipients r
  WHERE r.version_id = p_version_id
    AND (r.user_id = auth.uid() OR (v_person IS NOT NULL AND r.person_id = v_person))
  ORDER BY r.sent_at DESC NULLS LAST
  LIMIT 1;

  INSERT INTO public.hms_handbook_acknowledgements
    (handbook_id, version_id, company_id, user_id, person_id, recipient_id, section_id,
     confirmation_text, user_agent, method, confirmed_via)
  VALUES (ver.handbook_id, ver.id, ver.company_id, auth.uid(), v_person, v_recipient, p_section_id,
          p_confirmation_text, left(COALESCE(p_user_agent, ''), 250), 'system', 'internal')
  ON CONFLICT DO NOTHING;

  IF v_recipient IS NOT NULL AND p_section_id IS NULL THEN
    UPDATE public.hms_handbook_recipients
       SET acknowledged_at = COALESCE(acknowledged_at, now()),
           ack_method = COALESCE(ack_method, 'system')
     WHERE id = v_recipient;
  END IF;

  INSERT INTO public.hms_audit_log (company_id, entity_type, entity_id, action, payload)
  VALUES (ver.company_id, 'hms_handbook', ver.handbook_id, 'acknowledgement.recorded',
          jsonb_build_object('version_id', ver.id, 'section_id', p_section_id,
                             'confirmed_via', 'internal', 'person_id', v_person,
                             'recipient_id', v_recipient));

  RETURN jsonb_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.planning_sync_owner_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.owner_user_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.owner_user_id IS NOT DISTINCT FROM OLD.owner_user_id THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.owner_user_id IS NOT NULL THEN
    UPDATE public.planning_members SET role = 'member'
     WHERE planning_project_id = NEW.id AND user_id = OLD.owner_user_id AND role = 'owner';
  END IF;
  INSERT INTO public.planning_members (planning_project_id, user_id, role, member_type, created_by)
  VALUES (NEW.id, NEW.owner_user_id, 'owner', 'internal', auth.uid())
  ON CONFLICT (planning_project_id, user_id) WHERE user_id IS NOT NULL DO UPDATE SET role = 'owner';
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.create_work_visits_on_project_batch(p_parent_id uuid, p_client_request_id uuid, p_title text, p_technician_ids uuid[], p_dates jsonb, p_extra jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user uuid := auth.uid();
  _parent record;
  _root_id uuid;
  _results jsonb := '[]'::jsonb;
  _row jsonb;
  _date text;
  _start timestamptz;
  _end timestamptz;
  _per_req uuid;
  _event_id uuid;
  _existing_id uuid;
  _status text;
  _inserted_blocks int;
  _tech uuid;
  _err_msg text;
  _err_state text;
  _err_detail text;
  _err_hint text;
BEGIN
  IF p_parent_id IS NULL OR p_client_request_id IS NULL OR p_dates IS NULL OR jsonb_array_length(p_dates) = 0 THEN
    RAISE EXCEPTION 'missing required parameters';
  END IF;

  SELECT id, parent_project_id, project_type, company_id, title, customer, address, postal_code, city,
         location_details, site_contact_name, site_contact_phone, access_notes, map_link, description,
         customer_practical_info, source_order_form_id
    INTO _parent FROM public.events WHERE id = p_parent_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'parent project not found'; END IF;

  _root_id := CASE WHEN _parent.project_type = 'task' AND _parent.parent_project_id IS NOT NULL
                   THEN _parent.parent_project_id ELSE _parent.id END;

  IF _root_id <> _parent.id THEN
    SELECT id, parent_project_id, project_type, company_id, title, customer, address, postal_code, city,
           location_details, site_contact_name, site_contact_phone, access_notes, map_link, description,
           customer_practical_info, source_order_form_id
      INTO _parent FROM public.events WHERE id = _root_id AND deleted_at IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'root project not found'; END IF;
  END IF;

  FOR _row IN SELECT * FROM jsonb_array_elements(p_dates)
  LOOP
    _date := NULL; _start := NULL; _end := NULL;
    _per_req := NULL; _event_id := NULL; _existing_id := NULL;
    _status := 'created'; _inserted_blocks := 0;

    BEGIN
      _date := _row->>'date';
      _start := (_row->>'start')::timestamptz;
      _end := (_row->>'end')::timestamptz;

      IF _date IS NULL OR _start IS NULL OR _end IS NULL THEN
        _results := _results || jsonb_build_object('date', _date, 'status', 'failed', 'error', 'invalid date entry');
        CONTINUE;
      END IF;

      IF _end <= _start THEN
        _results := _results || jsonb_build_object(
          'date', _date, 'status', 'failed',
          'error', format('invalid time range: end (%s) must be after start (%s)', _end, _start),
          'sqlstate', '22023'
        );
        CONTINUE;
      END IF;

      _per_req := md5(p_client_request_id::text || '|' || _date)::uuid;

      IF p_technician_ids IS NOT NULL AND array_length(p_technician_ids, 1) > 0 THEN
        SELECT e.id INTO _existing_id
        FROM public.events e
        WHERE e.parent_project_id = _root_id
          AND e.project_type = 'task'
          AND e.deleted_at IS NULL
          AND e.start_time = _start
          AND e.end_time = _end
          AND EXISTS (
            SELECT 1 FROM public.event_technicians et
            WHERE et.event_id = e.id AND et.technician_id = ANY(p_technician_ids)
          )
        LIMIT 1;
      END IF;

      IF _existing_id IS NULL THEN
        SELECT id INTO _existing_id FROM public.events
         WHERE client_request_id = _per_req AND deleted_at IS NULL LIMIT 1;
      END IF;

      IF _existing_id IS NOT NULL THEN
        _event_id := _existing_id;
        _status := 'existing';
      ELSE
        INSERT INTO public.events (
          parent_project_id, project_type, title, customer, address, postal_code, city,
          location_details, site_contact_name, site_contact_phone, access_notes, map_link,
          description, customer_practical_info, start_time, end_time, technician_id, status,
          created_by, client_request_id, company_id, source_order_form_id
        ) VALUES (
          _root_id, 'task',
          COALESCE(NULLIF(p_title,''), _parent.title),
          _parent.customer, _parent.address, _parent.postal_code, _parent.city,
          _parent.location_details, _parent.site_contact_name, _parent.site_contact_phone,
          _parent.access_notes, _parent.map_link, _parent.description, _parent.customer_practical_info,
          _start, _end,
          COALESCE(p_technician_ids[1], _user),
          'requested', _user, _per_req, _parent.company_id, _parent.source_order_form_id
        ) RETURNING id INTO _event_id;
      END IF;

      IF p_technician_ids IS NOT NULL THEN
        FOREACH _tech IN ARRAY p_technician_ids LOOP
          INSERT INTO public.event_technicians (event_id, technician_id, start_at, end_at)
          VALUES (_event_id, _tech, _start, _end)
          ON CONFLICT (event_id, technician_id) DO UPDATE
            SET start_at = EXCLUDED.start_at, end_at = EXCLUDED.end_at;
        END LOOP;

        FOREACH _tech IN ARRAY p_technician_ids LOOP
          -- Broadened check: a schedule_block for this activity may already exist
          -- either via job_id (RPC pattern) or via project_id (older "new project"
          -- pattern where project_id == event.id). Treat both as existing so we
          -- never create a duplicate render card.
          IF NOT EXISTS (
            SELECT 1 FROM public.schedule_blocks sb
            WHERE sb.technician_id = _tech
              AND sb.start_at = _start
              AND sb.end_at = _end
              AND sb.deleted_at IS NULL
              AND (sb.job_id = _event_id OR sb.project_id = _event_id)
          ) THEN
            INSERT INTO public.schedule_blocks (
              company_id, technician_id, project_id, job_id, source, start_at, end_at,
              title, match_state, match_confidence, match_reason
            ) VALUES (
              _parent.company_id, _tech, _root_id, _event_id, 'manual', _start, _end,
              COALESCE(NULLIF(p_title,''), _parent.title),
              'manual', 100, 'Arbeidsbesøk via planlegger'
            );
            _inserted_blocks := _inserted_blocks + 1;
          END IF;
        END LOOP;
      END IF;

      IF _status = 'existing' AND _inserted_blocks > 0 THEN
        _status := 'repaired';
      END IF;

      BEGIN
        INSERT INTO public.event_logs (event_id, action_type, performed_by, change_summary, metadata)
        VALUES (_event_id, 'work_visit_' || _status, _user,
                CASE WHEN _status='created' THEN 'Arbeidsbesøk opprettet'
                     WHEN _status='repaired' THEN 'Arbeidsbesøk reparert (manglende planblokker)'
                     ELSE 'Arbeidsbesøk fantes fra før' END,
                jsonb_build_object('inserted_blocks', _inserted_blocks, 'root_id', _root_id, 'date', _date,
                                   'start', _start, 'end', _end,
                                   'overnight', (_start::date <> _end::date)));
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'event_logs insert skipped: %', SQLERRM;
      END;

      _results := _results || jsonb_build_object(
        'date', _date,
        'event_id', _event_id,
        'status', _status,
        'inserted_blocks', _inserted_blocks,
        'overnight', (_start::date <> _end::date)
      );
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS
        _err_msg = MESSAGE_TEXT,
        _err_state = RETURNED_SQLSTATE,
        _err_detail = PG_EXCEPTION_DETAIL,
        _err_hint = PG_EXCEPTION_HINT;

      RAISE WARNING 'create_work_visits_on_project_batch failed for date % (sqlstate %): % | detail: % | hint: %',
        _date, _err_state, _err_msg, _err_detail, _err_hint;

      _results := _results || jsonb_build_object(
        'date', _date, 'status', 'failed', 'error', _err_msg,
        'sqlstate', _err_state, 'detail', _err_detail, 'hint', _err_hint
      );
    END;
  END LOOP;

  RETURN jsonb_build_object('root_project_id', _root_id, 'results', _results);
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_create_commercial_case_for_calc_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _new_id uuid;
  _customer_id uuid;
BEGIN
  IF NEW.commercial_case_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- calc_cases har ikke alltid customer_id direkte; sjekk om kolonnen finnes via dynamic lookup
  BEGIN
    EXECUTE 'SELECT ($1).customer_id' INTO _customer_id USING NEW;
  EXCEPTION WHEN undefined_column THEN
    _customer_id := NULL;
  END;
  IF _customer_id IS NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.commercial_cases (company_id, title, customer_id, created_by, source, phase)
  VALUES (NEW.company_id, COALESCE(NEW.title, 'Kalkylesak'), _customer_id, NEW.created_by, 'calc', 'calculating')
  RETURNING id INTO _new_id;
  NEW.commercial_case_id := _new_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.planning_wp_sync_dates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE assigned int;
BEGIN
  IF NEW.linked_event_id IS NULL OR NEW.planned_start IS NULL THEN RETURN NEW; END IF;
  IF NEW.planned_start IS NOT DISTINCT FROM OLD.planned_start AND NEW.planned_end IS NOT DISTINCT FROM OLD.planned_end THEN RETURN NEW; END IF;
  SELECT count(*) INTO assigned FROM public.event_technicians WHERE event_id = NEW.linked_event_id;
  IF assigned = 0 THEN
    UPDATE public.events SET
      start_time = ((NEW.planned_start::text || ' 07:00')::timestamp AT TIME ZONE 'Europe/Oslo'),
      end_time = ((COALESCE(NEW.planned_end, NEW.planned_start)::text || ' 15:00')::timestamp AT TIME ZONE 'Europe/Oslo')
    WHERE id = NEW.linked_event_id AND deleted_at IS NULL AND technician_id IS NULL;
    INSERT INTO public.planning_activity (planning_project_id, action, summary, performed_by)
    VALUES (NEW.planning_project_id, 'resource_dates_synced', 'Datoer oppdatert i ressursplan: ' || NEW.name, auth.uid());
  ELSE
    INSERT INTO public.planning_activity (planning_project_id, action, summary, performed_by)
    VALUES (NEW.planning_project_id, 'resource_dates_mismatch', 'Dato endret på ' || NEW.name || ' – personer er allerede tildelt, så ressursplanen må justeres der', auth.uid());
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.mark_messages_read_by_token(_tracking_token text, _message_ids uuid[], _user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _submission_id uuid;
  _participant_id uuid;
  _last_msg_id uuid;
  _customer_name text;
  _customer_email text;
BEGIN
  SELECT id, COALESCE(submitter_name, 'Kunde'), submitter_email
    INTO _submission_id, _customer_name, _customer_email
  FROM order_form_submissions
  WHERE public_tracking_token = _tracking_token AND deleted_at IS NULL LIMIT 1;
  IF _submission_id IS NULL THEN RAISE EXCEPTION 'Invalid tracking token'; END IF;

  SELECT id INTO _participant_id FROM order_form_participants
    WHERE submission_id = _submission_id AND participant_type = 'customer' AND is_active = true
    ORDER BY created_at ASC LIMIT 1;
  IF _participant_id IS NULL THEN
    INSERT INTO order_form_participants (submission_id, participant_type, name, display_name, email, role_label, visibility, is_active)
    VALUES (_submission_id, 'customer', _customer_name, _customer_name, _customer_email, 'Bestiller', 'shared_with_customer', true)
    RETURNING id INTO _participant_id;
  END IF;

  SELECT id INTO _last_msg_id FROM order_form_messages
    WHERE submission_id = _submission_id AND is_visible_to_customer = true
    ORDER BY created_at DESC LIMIT 1;

  INSERT INTO order_form_message_reads (message_id, submission_id, participant_id, reader_type, user_agent, tracking_token_hash)
  SELECT m.id, _submission_id, _participant_id, 'customer', _user_agent, md5(_tracking_token)
  FROM order_form_messages m
  WHERE m.submission_id = _submission_id AND m.id = ANY(_message_ids) AND m.is_visible_to_customer = true
  ON CONFLICT (message_id, participant_id) DO NOTHING;

  UPDATE order_form_participants
    SET last_seen_at = now(), last_seen_message_id = COALESCE(_last_msg_id, last_seen_message_id)
    WHERE id = _participant_id;
  UPDATE order_form_submissions SET customer_last_viewed_at = now() WHERE id = _submission_id;

  RETURN jsonb_build_object('participant_id', _participant_id, 'submission_id', _submission_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_internal_conversation_participant(_submission_id uuid, _user_id uuid DEFAULT NULL::uuid, _technician_id uuid DEFAULT NULL::uuid, _display_name text DEFAULT NULL::text, _email text DEFAULT NULL::text, _phone text DEFAULT NULL::text, _role_label text DEFAULT 'Intern'::text, _visibility text DEFAULT 'internal'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _company_id uuid;
  _participant_id uuid;
  _ptype text;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF _user_id IS NULL AND _technician_id IS NULL THEN RAISE EXCEPTION 'Need user_id or technician_id'; END IF;
  SELECT company_id INTO _company_id FROM order_form_submissions WHERE id = _submission_id AND deleted_at IS NULL;
  IF _company_id IS NULL THEN RAISE EXCEPTION 'Submission not found'; END IF;
  IF NOT public.user_has_company_access(_uid, _company_id) THEN RAISE EXCEPTION 'Access denied'; END IF;

  _ptype := CASE WHEN _technician_id IS NOT NULL THEN 'technician' ELSE 'internal_user' END;

  IF _user_id IS NOT NULL THEN
    SELECT id INTO _participant_id FROM order_form_participants
      WHERE submission_id = _submission_id AND user_id = _user_id;
  ELSE
    SELECT id INTO _participant_id FROM order_form_participants
      WHERE submission_id = _submission_id AND technician_id = _technician_id;
  END IF;

  IF _participant_id IS NULL THEN
    INSERT INTO order_form_participants (
      submission_id, participant_type, user_id, technician_id, name, display_name, email, phone, role_label, visibility, added_by, is_active
    ) VALUES (
      _submission_id, _ptype, _user_id, _technician_id,
      COALESCE(_display_name, 'Deltaker'), COALESCE(_display_name, 'Deltaker'),
      _email, _phone, _role_label, _visibility, _uid, true
    ) RETURNING id INTO _participant_id;
  ELSE
    UPDATE order_form_participants SET
      is_active = true,
      display_name = COALESCE(_display_name, display_name),
      email = COALESCE(_email, email),
      phone = COALESCE(_phone, phone),
      role_label = COALESCE(_role_label, role_label),
      visibility = COALESCE(_visibility, visibility)
    WHERE id = _participant_id;
  END IF;
  RETURN _participant_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.deactivate_conversation_participant(_participant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _company_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Auth required'; END IF;
  SELECT s.company_id INTO _company_id FROM order_form_participants p
    JOIN order_form_submissions s ON s.id = p.submission_id WHERE p.id = _participant_id;
  IF _company_id IS NULL THEN RAISE EXCEPTION 'Not found'; END IF;
  IF NOT public.user_has_company_access(_uid, _company_id) THEN RAISE EXCEPTION 'Denied'; END IF;
  UPDATE order_form_participants SET is_active = false WHERE id = _participant_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_messages_read_internal(_submission_id uuid, _message_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _company_id uuid;
  _participant_id uuid;
  _full_name text;
  _email text;
  _last_msg_id uuid;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT company_id INTO _company_id FROM order_form_submissions
    WHERE id = _submission_id AND deleted_at IS NULL;
  IF _company_id IS NULL THEN RAISE EXCEPTION 'Submission not found'; END IF;
  IF NOT (public.user_has_company_access(_uid, _company_id)
          OR public.has_cross_company_order_access(_uid, _submission_id)) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT id INTO _participant_id FROM order_form_participants
    WHERE submission_id = _submission_id AND user_id = _uid AND is_active = true LIMIT 1;

  IF _participant_id IS NULL THEN
    SELECT p.full_name, p.email INTO _full_name, _email
    FROM user_accounts ua LEFT JOIN people p ON p.id = ua.person_id
    WHERE ua.auth_user_id = _uid AND ua.is_active = true LIMIT 1;
    INSERT INTO order_form_participants (
      submission_id, participant_type, user_id, name, display_name, email,
      role_label, visibility, added_by, is_active
    ) VALUES (
      _submission_id, 'internal_user', _uid,
      COALESCE(_full_name, 'Intern bruker'),
      COALESCE(_full_name, 'Intern bruker'),
      _email, 'Intern', 'internal', _uid, true
    ) RETURNING id INTO _participant_id;
  END IF;

  SELECT id INTO _last_msg_id FROM order_form_messages
    WHERE submission_id = _submission_id ORDER BY created_at DESC LIMIT 1;

  INSERT INTO order_form_message_reads (message_id, submission_id, participant_id, reader_type, user_id)
  SELECT m.id, _submission_id, _participant_id, 'internal_user', _uid
  FROM order_form_messages m
  WHERE m.submission_id = _submission_id AND m.id = ANY(_message_ids)
  ON CONFLICT (message_id, participant_id) DO NOTHING;

  UPDATE order_form_participants
    SET last_seen_at = now(),
        last_seen_message_id = COALESCE(_last_msg_id, last_seen_message_id)
    WHERE id = _participant_id;

  RETURN jsonb_build_object('participant_id', _participant_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_job_approval_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tech_name   text;
  v_job_title   text;
  v_job_number  text;
  v_link        text;
  v_notif_type  text;
  v_message     text;
  v_admin       uuid;
  v_all_approved boolean;
  v_total       int;
  v_approved    int;
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.status NOT IN ('approved','rejected','declined','reschedule_requested','change_request') THEN
    RETURN NEW;
  END IF;

  -- Tech name
  SELECT name INTO v_tech_name
    FROM public.technicians
   WHERE user_id = NEW.technician_user_id
   LIMIT 1;
  v_tech_name := COALESCE(v_tech_name, 'Montør');

  -- Job info
  SELECT title, COALESCE(job_number, internal_number, project_number)
    INTO v_job_title, v_job_number
    FROM public.events
   WHERE id = NEW.job_id;

  v_link := '/projects/' || NEW.job_id::text;
  v_job_number := COALESCE(v_job_number, v_job_title, 'jobb');

  v_notif_type := CASE
    WHEN NEW.status = 'approved' THEN 'approved'
    WHEN NEW.status IN ('rejected','declined') THEN 'rejected'
    ELSE 'time_change_proposed'
  END;

  v_message := CASE
    WHEN NEW.status = 'approved' THEN v_tech_name || ' godkjente ' || v_job_number
    WHEN NEW.status IN ('rejected','declined') THEN v_tech_name || ' avslo ' || v_job_number || COALESCE(' – ' || NEW.comment, '')
    ELSE v_tech_name || ' foreslo nytt tidspunkt for ' || v_job_number
  END;

  FOR v_admin IN SELECT public._notif_admin_user_ids() LOOP
    INSERT INTO public.notifications
      (user_id, event_id, type, title, message, link_url, priority,
       entity_type, entity_id, actor_user_id, actor_name)
    VALUES
      (v_admin, NEW.job_id, v_notif_type, v_job_number, v_message, v_link,
       CASE WHEN NEW.status = 'approved' THEN 'info' ELSE 'important' END,
       'event', NEW.job_id, NEW.technician_user_id, v_tech_name)
    ON CONFLICT DO NOTHING;
  END LOOP;

  -- Check "all approved"
  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'approved')
    INTO v_total, v_approved
    FROM public.job_approvals
   WHERE job_id = NEW.job_id;

  IF v_total > 0 AND v_total = v_approved THEN
    FOR v_admin IN SELECT public._notif_admin_user_ids() LOOP
      INSERT INTO public.notifications
        (user_id, event_id, type, title, message, link_url, priority,
         entity_type, entity_id)
      VALUES
        (v_admin, NEW.job_id, 'all_approved', v_job_number,
         v_job_number || ' er godkjent av alle (' || v_total || ' montører)',
         v_link, 'info', 'event', NEW.job_id)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.planning_activity_fill_actor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.performed_by IS NULL THEN NEW.performed_by := auth.uid(); END IF;
  IF NEW.performed_by IS NOT NULL AND (NEW.performed_by_name IS NULL OR NEW.performed_by_name = '') THEN
    SELECT name INTO NEW.performed_by_name FROM public.technicians WHERE user_id = NEW.performed_by AND name IS NOT NULL LIMIT 1;
    IF NEW.performed_by_name IS NULL THEN
      SELECT pe.full_name INTO NEW.performed_by_name FROM public.user_accounts ua JOIN public.people pe ON pe.id = ua.person_id
       WHERE ua.auth_user_id = NEW.performed_by LIMIT 1;
    END IF;
    IF NEW.performed_by_name IS NULL THEN
      SELECT email INTO NEW.performed_by_name FROM auth.users WHERE id = NEW.performed_by;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.update_commercial_case_crm(_case_id uuid, _phase text DEFAULT NULL::text, _owner_user_id uuid DEFAULT NULL::uuid, _next_step text DEFAULT NULL::text, _next_step_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _value_estimate numeric DEFAULT NULL::numeric, _probability_pct numeric DEFAULT NULL::numeric, _expected_close_date date DEFAULT NULL::date, _description text DEFAULT NULL::text)
 RETURNS commercial_cases
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _existing public.commercial_cases;
  _updated public.commercial_cases;
  _summary text;
  _changes text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO _existing FROM public.commercial_cases WHERE id = _case_id AND deleted_at IS NULL;
  IF _existing.id IS NULL THEN
    RAISE EXCEPTION 'Commercial case not found: %', _case_id;
  END IF;

  IF NOT public.user_has_company_access(auth.uid(), _existing.company_id) THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  UPDATE public.commercial_cases SET
    phase              = COALESCE(_phase, phase),
    owner_user_id      = COALESCE(_owner_user_id, owner_user_id),
    next_step          = COALESCE(_next_step, next_step),
    next_step_due_at   = COALESCE(_next_step_due_at, next_step_due_at),
    value_estimate     = COALESCE(_value_estimate, value_estimate),
    probability_pct    = COALESCE(_probability_pct, probability_pct),
    expected_close_date = COALESCE(_expected_close_date, expected_close_date),
    description        = COALESCE(_description, description),
    won_at             = CASE WHEN _phase = 'won' AND _existing.won_at IS NULL THEN now() ELSE won_at END,
    lost_at            = CASE WHEN _phase = 'lost' AND _existing.lost_at IS NULL THEN now() ELSE lost_at END,
    updated_at         = now()
  WHERE id = _case_id
  RETURNING * INTO _updated;

  -- Bygg change-summary
  IF _phase IS NOT NULL AND _phase IS DISTINCT FROM _existing.phase THEN
    _changes := array_append(_changes, 'fase: ' || COALESCE(_existing.phase,'—') || ' → ' || _phase);
  END IF;
  IF _owner_user_id IS NOT NULL AND _owner_user_id IS DISTINCT FROM _existing.owner_user_id THEN
    _changes := array_append(_changes, 'ansvarlig endret');
  END IF;
  IF _next_step IS NOT NULL AND _next_step IS DISTINCT FROM _existing.next_step THEN
    _changes := array_append(_changes, 'neste steg oppdatert');
  END IF;
  IF _value_estimate IS NOT NULL AND _value_estimate IS DISTINCT FROM _existing.value_estimate THEN
    _changes := array_append(_changes, 'verdi oppdatert');
  END IF;

  IF array_length(_changes, 1) > 0 THEN
    _summary := array_to_string(_changes, ', ');
    INSERT INTO public.activity_log (
      entity_type, entity_id, commercial_case_id,
      action, type, title, description,
      performed_by, visibility, metadata
    ) VALUES (
      'commercial_case', _case_id, _case_id,
      'crm_update', 'status_change', 'Sak oppdatert', _summary,
      auth.uid(), 'internal',
      jsonb_build_object('summary', _summary)
    );
  END IF;

  RETURN _updated;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_company_module_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE act text;
BEGIN
  IF TG_OP = 'INSERT' THEN act := 'granted';
  ELSIF NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL THEN act := 'revoked';
  ELSE act := 'changed'; END IF;
  INSERT INTO public.access_audit_log(user_id, home_company_id, company_id, module, level, action, details, performed_by)
  VALUES (NEW.user_id, public.home_company_of(NEW.user_id), NEW.company_id, NEW.module, NEW.level, act,
    jsonb_build_object('reason', NEW.reason, 'valid_from', NEW.valid_from, 'valid_to', NEW.valid_to,
      'old_level', CASE WHEN TG_OP = 'UPDATE' THEN OLD.level END),
    COALESCE(auth.uid(), NEW.granted_by));
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.auto_create_commercial_case_for_calculation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _new_id uuid;
  _case_commercial_id uuid;
BEGIN
  IF NEW.commercial_case_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  -- Hvis kalkylen er knyttet til en calc_case, arver den dens commercial_case
  IF NEW.case_id IS NOT NULL THEN
    SELECT commercial_case_id INTO _case_commercial_id
    FROM public.calc_cases WHERE id = NEW.case_id;
    IF _case_commercial_id IS NOT NULL THEN
      NEW.commercial_case_id := _case_commercial_id;
      RETURN NEW;
    END IF;
  END IF;
  -- Revisjoner arver fra rot
  IF NEW.parent_offer_id IS NOT NULL THEN
    SELECT commercial_case_id INTO _case_commercial_id
    FROM public.calculations WHERE id = NEW.parent_offer_id;
    IF _case_commercial_id IS NOT NULL THEN
      NEW.commercial_case_id := _case_commercial_id;
      RETURN NEW;
    END IF;
  END IF;
  -- Frittstående: krever customer
  IF NEW.customer_id IS NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.commercial_cases (company_id, title, customer_id, contact_person_id, created_by, source, phase, value_estimate)
  VALUES (
    NEW.company_id,
    COALESCE(NEW.project_title, 'Kalkyle/Tilbud'),
    NEW.customer_id,
    NEW.contact_person_id,
    NEW.created_by,
    'calc',
    'calculating',
    NEW.total_price
  )
  RETURNING id INTO _new_id;
  NEW.commercial_case_id := _new_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.answer_field_request_by_token(_token text, _request_id uuid, _value jsonb, _submitter_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _submission record;
  _request record;
  _value_text text;
BEGIN
  -- Validate token + request belong together
  SELECT s.id, s.company_id, s.submission_no, s.status
  INTO _submission
  FROM public.order_form_submissions s
  WHERE s.public_tracking_token = _token
    AND s.deleted_at IS NULL;

  IF _submission.id IS NULL THEN
    RETURN jsonb_build_object('error', 'invalid_token');
  END IF;

  SELECT * INTO _request
  FROM public.order_form_field_requests
  WHERE id = _request_id
    AND submission_id = _submission.id;

  IF _request.id IS NULL THEN
    RETURN jsonb_build_object('error', 'request_not_found');
  END IF;

  IF _request.status <> 'open' THEN
    RETURN jsonb_build_object('error', 'already_answered');
  END IF;

  -- Mark request as answered
  UPDATE public.order_form_field_requests
  SET status = 'answered',
      answer_value = _value,
      answered_at = now(),
      updated_at = now()
  WHERE id = _request_id;

  -- If it maps to a template field, also write the value into submission_values
  IF _request.field_key IS NOT NULL AND _request.field_key <> '' THEN
    DELETE FROM public.order_form_submission_values
      WHERE submission_id = _submission.id AND field_key = _request.field_key;
    IF _value IS NOT NULL AND jsonb_typeof(_value) <> 'null' THEN
      INSERT INTO public.order_form_submission_values (submission_id, field_key, value)
      VALUES (_submission.id, _request.field_key, _value);
    END IF;
  END IF;

  -- Convert value to display text
  IF jsonb_typeof(_value) = 'string' THEN
    _value_text := _value #>> '{}';
  ELSE
    _value_text := _value::text;
  END IF;

  -- Activity log
  INSERT INTO public.order_form_activity_log (submission_id, event_type, payload)
  VALUES (
    _submission.id,
    'customer_filled_field',
    jsonb_build_object(
      'request_id', _request_id,
      'field_key', _request.field_key,
      'field_label', _request.field_label,
      'is_free_text', _request.is_free_text,
      'value_display', LEFT(COALESCE(_value_text, ''), 500),
      'submitter_name', _submitter_name,
      'summary', _request.field_label || ' fylt inn av bestiller'
    )
  );

  -- Touch submission timestamps
  UPDATE public.order_form_submissions
  SET last_activity_at = now(),
      customer_last_reply_at = now(),
      last_customer_message_at = now(),
      updated_at = now()
  WHERE id = _submission.id;

  RETURN jsonb_build_object('ok', true, 'request_id', _request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_schedule_block_for_event_technician()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _event RECORD;
  _start_at TIMESTAMPTZ;
  _end_at TIMESTAMPTZ;
  _existing_block_id UUID;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Soft-delete linked auto-generated blocks for this assignment
    UPDATE public.schedule_blocks
    SET deleted_at = now(),
        deleted_reason = 'event_technician removed',
        updated_at = now()
    WHERE project_id = OLD.event_id
      AND technician_id = OLD.technician_id
      AND source IN ('manual', 'system')
      AND deleted_at IS NULL;
    RETURN OLD;
  END IF;

  -- Look up event for company_id, fallback times, title
  SELECT id, company_id, start_time, end_time, title, address, deleted_at
  INTO _event
  FROM public.events
  WHERE id = NEW.event_id;

  IF _event.id IS NULL OR _event.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Use per-tech overrides when available, else fall back to event times
  _start_at := COALESCE(NEW.start_at, _event.start_time);
  _end_at := COALESCE(NEW.end_at, _event.end_time);

  IF _start_at IS NULL OR _end_at IS NULL THEN
    RETURN NEW;
  END IF;

  -- Find any existing non-deleted block for this assignment that overlaps the
  -- assignment time window. We only auto-manage blocks created by us
  -- (source IN ('manual','system')). Outlook-imported blocks are left alone.
  SELECT id INTO _existing_block_id
  FROM public.schedule_blocks
  WHERE project_id = NEW.event_id
    AND technician_id = NEW.technician_id
    AND source IN ('manual', 'system')
    AND deleted_at IS NULL
    AND start_at = _start_at
    AND end_at = _end_at
  LIMIT 1;

  IF TG_OP = 'INSERT' THEN
    -- Only create a new block if no exact-match block exists
    IF _existing_block_id IS NULL THEN
      INSERT INTO public.schedule_blocks (
        company_id, technician_id, project_id, source,
        start_at, end_at, title, location,
        match_state, match_confidence, match_reason
      ) VALUES (
        _event.company_id, NEW.technician_id, NEW.event_id, 'manual',
        _start_at, _end_at, COALESCE(_event.title, 'Prosjektarbeid'), _event.address,
        'manual', 100, 'Auto-synkronisert fra event_technicians'
      );
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- If start/end changed and there's no exact-match block, update the most
    -- recent active block for this assignment to the new times. This keeps a
    -- single block per (event, technician) when planner edits times.
    IF (OLD.start_at IS DISTINCT FROM NEW.start_at) OR (OLD.end_at IS DISTINCT FROM NEW.end_at) THEN
      IF _existing_block_id IS NULL THEN
        UPDATE public.schedule_blocks
        SET start_at = _start_at,
            end_at = _end_at,
            updated_at = now()
        WHERE id = (
          SELECT id FROM public.schedule_blocks
          WHERE project_id = NEW.event_id
            AND technician_id = NEW.technician_id
            AND source IN ('manual', 'system')
            AND deleted_at IS NULL
          ORDER BY updated_at DESC
          LIMIT 1
        );

        -- If no block existed at all, create one
        IF NOT FOUND THEN
          INSERT INTO public.schedule_blocks (
            company_id, technician_id, project_id, source,
            start_at, end_at, title, location,
            match_state, match_confidence, match_reason
          ) VALUES (
            _event.company_id, NEW.technician_id, NEW.event_id, 'manual',
            _start_at, _end_at, COALESCE(_event.title, 'Prosjektarbeid'), _event.address,
            'manual', 100, 'Auto-synkronisert fra event_technicians (update)'
          );
        END IF;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_duplicate_schedule_blocks_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _affected int;
  _groups int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'Only super_admin may run schedule-block cleanup';
  END IF;

  WITH ranked AS (
    SELECT
      sb.id,
      row_number() OVER (
        PARTITION BY sb.job_id, sb.project_id, sb.technician_id, sb.start_at, sb.end_at, sb.source
        ORDER BY sb.created_at ASC NULLS LAST, sb.id ASC
      ) AS rn,
      count(*) OVER (
        PARTITION BY sb.job_id, sb.project_id, sb.technician_id, sb.start_at, sb.end_at, sb.source
      ) AS dc
    FROM public.schedule_blocks sb
    WHERE sb.deleted_at IS NULL
  ),
  to_delete AS (
    SELECT id FROM ranked WHERE rn > 1 AND dc > 1
  ),
  upd AS (
    UPDATE public.schedule_blocks sb
    SET deleted_at = now(),
        deleted_reason = 'duplicate_schedule_block_cleanup',
        updated_at = now()
    FROM to_delete td
    WHERE sb.id = td.id
      AND sb.deleted_at IS NULL
    RETURNING sb.id
  )
  SELECT count(*) INTO _affected FROM upd;

  SELECT count(*) INTO _groups FROM public.dry_run_duplicate_schedule_blocks();

  RAISE NOTICE '[schedule_blocks cleanup] soft-deleted % rows, remaining duplicate groups: %', _affected, _groups;

  RETURN jsonb_build_object(
    'soft_deleted', _affected,
    'remaining_duplicate_groups', _groups,
    'ran_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_create_commercial_case_for_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _new_id uuid;
  _row jsonb;
  _customer_id uuid;
  _contact_person_id uuid;
  _title text;
BEGIN
  IF NEW.commercial_case_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.company_id IS NULL THEN
    RETURN NEW;
  END IF;

  _row := to_jsonb(NEW);
  _customer_id := NULLIF(_row->>'customer_id','')::uuid;
  _contact_person_id := NULLIF(_row->>'contact_person_id','')::uuid;
  _title := COALESCE(
    NULLIF(_row->>'title',''),
    NULLIF(_row->>'subject',''),
    NULLIF(_row->>'company_name',''),
    'Lead'
  );

  -- Only auto-create commercial case when a customer is linked
  IF _customer_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.commercial_cases (company_id, title, customer_id, contact_person_id, created_by, source, phase)
  VALUES (
    NEW.company_id,
    _title,
    _customer_id,
    _contact_person_id,
    NULLIF(_row->>'created_by','')::uuid,
    'lead',
    'lead'
  )
  RETURNING id INTO _new_id;
  NEW.commercial_case_id := _new_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rename_submission_attachment(_attachment_id uuid, _display_name text, _description text DEFAULT NULL::text)
 RETURNS order_form_submission_attachments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.order_form_submission_attachments;
  _company uuid;
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT s.company_id INTO _company
  FROM public.order_form_submission_attachments a
  JOIN public.order_form_submissions s ON s.id = a.submission_id
  WHERE a.id = _attachment_id;

  IF _company IS NULL THEN
    RAISE EXCEPTION 'Attachment not found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_memberships um
    WHERE um.user_id = _uid AND um.company_id = _company
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.order_form_submission_attachments
  SET display_name = NULLIF(btrim(_display_name), ''),
      description  = NULLIF(btrim(_description), ''),
      renamed_at   = now(),
      renamed_by   = _uid
  WHERE id = _attachment_id
  RETURNING * INTO _row;

  RETURN _row;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_planning_wp_to_resource_plan(_wp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE w record; p record; ev record; new_id uuid; cust text;
BEGIN
  SELECT * INTO w FROM public.planning_work_packages WHERE id = _wp_id FOR UPDATE;
  IF w.id IS NULL OR NOT public.has_planning_project_access(w.planning_project_id) THEN
    RAISE EXCEPTION 'Mangler tilgang' USING ERRCODE = '42501';
  END IF;
  IF w.planned_start IS NULL THEN
    RAISE EXCEPTION 'Sett planlagt start før arbeidspakken sendes til ressursplan';
  END IF;

  -- Allerede sendt og fortsatt aktiv: returner eksisterende
  SELECT id, project_number INTO ev FROM public.events
   WHERE deleted_at IS NULL AND (id = w.linked_event_id OR planning_work_package_id = w.id) LIMIT 1;
  IF ev.id IS NOT NULL THEN
    UPDATE public.planning_work_packages SET linked_event_id = ev.id,
      assignment_state = CASE WHEN assignment_state = 'not_assigned' THEN 'in_resource_plan' ELSE assignment_state END
     WHERE id = w.id;
    RETURN jsonb_build_object('event_id', ev.id, 'project_number', ev.project_number, 'created', false);
  END IF;

  SELECT * INTO p FROM public.planning_projects WHERE id = w.planning_project_id;
  SELECT name INTO cust FROM public.customers WHERE id = p.customer_id;

  INSERT INTO public.events (title, description, start_time, end_time, status, project_type,
     company_id, department_id, customer, customer_id, created_by,
     planning_project_id, planning_work_package_id)
  VALUES (
     p.name || ' – ' || w.name,
     concat_ws(E'\n\n', w.description,
       CASE WHEN w.resource_count IS NOT NULL OR w.estimated_hours IS NOT NULL THEN
         'Ressursbehov: ' || concat_ws(' · ', CASE WHEN w.resource_count IS NOT NULL THEN w.resource_count || ' personer' END,
                                             CASE WHEN w.estimated_hours IS NOT NULL THEN w.estimated_hours || ' timer' END) END),
     ((w.planned_start::text || ' 07:00')::timestamp AT TIME ZONE 'Europe/Oslo'),
     ((COALESCE(w.planned_end, w.planned_start)::text || ' 15:00')::timestamp AT TIME ZONE 'Europe/Oslo'),
     'requested', 'project',
     COALESCE(w.responsible_company_id, p.company_id), COALESCE(w.responsible_department_id, p.department_id),
     cust, p.customer_id, auth.uid(), p.id, w.id)
  RETURNING id INTO new_id;

  UPDATE public.planning_work_packages SET linked_event_id = new_id, assignment_state = 'in_resource_plan', updated_at = now() WHERE id = w.id;
  INSERT INTO public.planning_activity (planning_project_id, action, summary, performed_by, metadata)
  VALUES (p.id, 'sent_to_resource_plan', 'Ressursbehov sendt til ressursplan: ' || w.name, auth.uid(), jsonb_build_object('event_id', new_id, 'work_package_id', w.id));

  SELECT project_number INTO ev FROM public.events WHERE id = new_id;
  RETURN jsonb_build_object('event_id', new_id, 'project_number', ev.project_number, 'created', true);
END $function$

CREATE OR REPLACE FUNCTION public.enforce_tripletex_link_connection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record;
BEGIN
  IF NEW.connection_id IS NULL THEN RAISE EXCEPTION 'tripletex_links.connection_id is required'; END IF;
  SELECT * INTO c FROM tripletex_connections WHERE id = NEW.connection_id;
  IF c.company_id <> NEW.company_id OR c.environment <> NEW.environment
     OR (NEW.tripletex_company_id IS NOT NULL AND c.expected_tripletex_company_id IS DISTINCT FROM NEW.tripletex_company_id) THEN
    RAISE EXCEPTION 'Tripletex link does not match its connection (company/environment/Tripletex company)';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.log_org_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  changes jsonb := '{}'::jsonb;
  col text;
  act text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    act := 'created';
    changes := jsonb_build_object('title', NEW.title, 'person_id', NEW.person_id, 'role_type', NEW.role_type);
  ELSE
    IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
      act := 'deleted';
    ELSE
      act := 'updated';
      FOREACH col IN ARRAY ARRAY['title','role_type','person_id','deputy_person_id','reports_to_id','responsibilities','tasks','authority','valid_from','valid_to','is_active','additional_person_ids'] LOOP
        IF (to_jsonb(OLD)->col) IS DISTINCT FROM (to_jsonb(NEW)->col) THEN
          changes := changes || jsonb_build_object(col, jsonb_build_object('old', to_jsonb(OLD)->col, 'new', to_jsonb(NEW)->col));
        END IF;
      END LOOP;
      IF changes = '{}'::jsonb THEN RETURN NEW; END IF;
    END IF;
  END IF;
  INSERT INTO public.hms_audit_log(company_id, entity_type, entity_id, action, performed_by, payload)
  VALUES (NEW.company_id, 'org_role', NEW.id, act, auth.uid(), jsonb_build_object('title', NEW.title, 'changes', changes));
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_event_entity_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record;
BEGIN
  IF NEW.external_tripletex_id IS NOT NULL AND NEW.entity_type IN ('job','service','internal')
     AND (TG_OP = 'INSERT' OR NEW.external_tripletex_id IS DISTINCT FROM OLD.external_tripletex_id OR NEW.entity_type IS DISTINCT FROM OLD.entity_type) THEN
    RAISE EXCEPTION 'Kun økonomiske prosjekter kan kobles til Tripletex';
  END IF;
  IF NEW.entity_type = 'financial_project' AND NEW.parent_project_id IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW.entity_type IS DISTINCT FROM OLD.entity_type OR NEW.parent_project_id IS DISTINCT FROM OLD.parent_project_id) THEN
    RAISE EXCEPTION 'Et økonomisk prosjekt kan ikke ligge under et annet prosjekt';
  END IF;
  IF NEW.parent_project_id IS NOT NULL AND NEW.entity_type IN ('job','service')
     AND (TG_OP = 'INSERT' OR NEW.parent_project_id IS DISTINCT FROM OLD.parent_project_id OR NEW.entity_type IS DISTINCT FROM OLD.entity_type) THEN
    SELECT entity_type, company_id INTO p FROM public.events WHERE id = NEW.parent_project_id;
    IF p.entity_type IS DISTINCT FROM 'financial_project' THEN
      RAISE EXCEPTION 'Jobb/serviceoppdrag må ligge under et økonomisk prosjekt';
    END IF;
    IF p.company_id IS DISTINCT FROM NEW.company_id THEN
      RAISE EXCEPTION 'Overordnet prosjekt må tilhøre samme selskap';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_tripletex_link_entity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.mcs_entity_type = 'project' AND NOT EXISTS (SELECT 1 FROM public.events WHERE id = NEW.mcs_entity_id AND entity_type = 'financial_project') THEN
    RAISE EXCEPTION 'Kun økonomiske prosjekter kan kobles til Tripletex';
  END IF;
  -- Employee links point at the canonical Hub person (people.id), never a technicians.id.
  IF NEW.mcs_entity_type = 'employee' AND NEW.status <> 'inactive' AND NOT EXISTS (
    SELECT 1 FROM public.people p JOIN public.employment_profiles ep ON ep.person_id = p.id
    WHERE p.id = NEW.mcs_entity_id AND ep.archived_at IS NULL AND ep.company_id = NEW.company_id) THEN
    RAISE EXCEPTION 'Ansattkobling må peke på en Hub-person med aktivt ansettelsesforhold i samme selskap som tilkoblingen';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tripletex_import_project_shell(_connection_id uuid, _tripletex_id bigint, _number text, _name text, _version integer, _customer_id uuid, _start date, _end date, _actor uuid)
 RETURNS TABLE(event_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; existing uuid; ev uuid;
BEGIN
  SELECT * INTO c FROM tripletex_connections WHERE id = _connection_id;
  IF c.id IS NULL OR c.environment <> 'test' THEN RAISE EXCEPTION 'Kun Tripletex TEST er tillatt'; END IF;
  IF NOT EXISTS (SELECT 1 FROM customers WHERE id = _customer_id AND company_id = c.company_id) THEN
    RAISE EXCEPTION 'Kunden tilhører ikke selskapet til tilkoblingen';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('tpx_import:' || _connection_id::text || ':' || _tripletex_id::text, 0));
  SELECT mcs_entity_id INTO existing FROM tripletex_links
   WHERE connection_id = _connection_id AND mcs_entity_type = 'project' AND tripletex_id = _tripletex_id AND status <> 'inactive';
  IF existing IS NOT NULL THEN RETURN QUERY SELECT existing, false; RETURN; END IF;
  INSERT INTO events (title, project_number, entity_type, classification_status, project_type, company_id, customer_id,
                      start_time, end_time, created_by)
  VALUES (_name, _number, 'financial_project', 'confirmed', 'project', c.company_id, _customer_id,
          coalesce(_start, current_date)::timestamptz, coalesce(_end, _start, current_date)::timestamptz, _actor)
  RETURNING id INTO ev;
  INSERT INTO tripletex_links (connection_id, company_id, environment, tripletex_company_id, mcs_entity_type, mcs_entity_id,
                               tripletex_id, tripletex_number, tripletex_name, tripletex_version, link_source, status, created_by, last_verified_at)
  VALUES (_connection_id, c.company_id, c.environment, c.expected_tripletex_company_id, 'project', ev,
          _tripletex_id, _number, _name, _version, 'imported_from_tripletex', 'active', _actor, now());
  RETURN QUERY SELECT ev, true;
END $function$

CREATE OR REPLACE FUNCTION public.hms_action_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rid uuid; r public.hms_risk_register; other_id uuid; tenant uuid;
BEGIN
 IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'Selskap er låst'; END IF;
 IF TG_OP<>'DELETE' THEN
  IF NEW.risk_register_id IS NOT NULL THEN
   SELECT * INTO r FROM public.hms_risk_register WHERE id=NEW.risk_register_id FOR UPDATE;
   IF NOT FOUND OR r.company_id<>NEW.company_id OR r.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Risiko tilhører ikke selskapet'; END IF;
   IF TG_OP='INSERT' THEN
    SELECT id INTO other_id FROM public.hms_action_items WHERE company_id=NEW.company_id AND risk_register_id=NEW.risk_register_id AND title=NEW.title AND coalesce(description,'')=coalesce(NEW.description,'') AND deleted_at IS NULL LIMIT 1;
    IF other_id IS NOT NULL THEN RAISE EXCEPTION 'Identisk tiltak finnes allerede'; END IF;
   END IF;
  END IF;
  IF NEW.year_activity_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hms_year_activities WHERE id=NEW.year_activity_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Årshjul tilhører ikke selskapet'; END IF;
  IF NEW.internal_review_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hms_internal_reviews WHERE id=NEW.internal_review_id AND company_id=NEW.company_id AND status<>'completed') THEN RAISE EXCEPTION 'Gjennomgang tilhører ikke selskapet eller er signert'; END IF;
  IF auth.uid() IS NOT NULL AND NOT public.has_company_access(auth.uid(),NEW.company_id,'hms','edit') THEN
   IF TG_OP<>'UPDATE' OR OLD.assignee_user_id IS DISTINCT FROM auth.uid() OR (to_jsonb(NEW)-ARRAY['status','completed_at','completed_by','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','completed_at','completed_by','updated_at']) OR NEW.status<>'done' THEN RAISE EXCEPTION 'Montør kan kun fullføre eget tiltak'; END IF;
   NEW.completed_by:=auth.uid(); NEW.completed_at:=now();
  END IF;
 END IF;
 rid:=CASE WHEN TG_OP='DELETE' THEN OLD.risk_register_id ELSE NEW.risk_register_id END;
 IF rid IS NOT NULL AND (TG_OP<>'UPDATE' OR NEW.status IS DISTINCT FROM OLD.status OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at) THEN
  UPDATE public.hms_risk_register SET residual_review_required=true,updated_at=now() WHERE id=rid;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hms_risk_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.probability IS DISTINCT FROM OLD.probability OR NEW.consequence IS DISTINCT FROM OLD.consequence THEN RAISE EXCEPTION 'Opprinnelig risiko og selskap er historisk låst'; END IF;
 END IF;
 IF NEW.probability NOT BETWEEN 1 AND 5 OR NEW.consequence NOT BETWEEN 1 AND 5 OR (NEW.rest_sannsynlighet IS NOT NULL AND NEW.rest_sannsynlighet NOT BETWEEN 1 AND 5) OR (NEW.rest_konsekvens IS NOT NULL AND NEW.rest_konsekvens NOT BETWEEN 1 AND 5) THEN RAISE EXCEPTION 'Risiko må være mellom 1 og 5'; END IF;
 IF NEW.status NOT IN ('active','mitigated','closed') THEN RAISE EXCEPTION 'Ugyldig risikostatus'; END IF;
 IF TG_OP='INSERT' AND NEW.status<>'active' THEN RAISE EXCEPTION 'Ny risiko opprettes som aktiv før rest-risikovurdering'; END IF;
 IF TG_OP='UPDATE' AND (NEW.rest_sannsynlighet IS DISTINCT FROM OLD.rest_sannsynlighet OR NEW.rest_konsekvens IS DISTINCT FROM OLD.rest_konsekvens OR NEW.residual_reviewed_at IS DISTINCT FROM OLD.residual_reviewed_at OR NEW.status IS DISTINCT FROM OLD.status OR (OLD.residual_review_required AND NOT NEW.residual_review_required)) THEN
  IF NEW.residual_reviewed_at IS NULL OR NEW.rest_sannsynlighet IS NULL OR NEW.rest_konsekvens IS NULL OR length(trim(coalesce(NEW.residual_comment,'')))=0 THEN RAISE EXCEPTION 'Dokumenter eksplisitt rest-risikovurdering'; END IF;
  IF NOT public.has_company_access(auth.uid(),NEW.company_id,'hms','edit') OR (NEW.responsible_user_id IS NOT NULL AND NEW.responsible_user_id<>auth.uid() AND NOT public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'Ansvarlig må vurdere rest-risiko'; END IF;
  NEW.residual_reviewed_by:=auth.uid(); NEW.residual_reviewed_at:=now(); NEW.residual_review_required:=false;
 END IF;
 IF NEW.status IN ('mitigated','closed') AND (NEW.rest_sannsynlighet IS NULL OR NEW.rest_konsekvens IS NULL) THEN RAISE EXCEPTION 'Rest-risiko må vurderes eksplisitt før Redusert/Lukket'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hms_complete_own_action(_company_id uuid, _action_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Innlogging kreves'; END IF;
 UPDATE public.hms_action_items SET status='done',completed_by=auth.uid(),completed_at=now(),updated_at=now() WHERE id=_action_id AND company_id=_company_id AND assignee_user_id=[REDACTED] AND deleted_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Eget tiltak finnes ikke i selskapet'; END IF;
 RETURN _action_id;
END $function$

CREATE OR REPLACE FUNCTION public.hms_control_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE old_value jsonb; new_value jsonb; changed jsonb; row_value jsonb;
BEGIN
 old_value:=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
 new_value:=CASE WHEN TG_OP='DELETE' THEN '{}'::jsonb ELSE to_jsonb(NEW) END;
 SELECT coalesce(jsonb_object_agg(k,jsonb_build_object('old',old_value->k,'new',new_value->k)),'{}'::jsonb) INTO changed FROM (SELECT jsonb_object_keys(old_value||new_value) k) keys WHERE old_value->k IS DISTINCT FROM new_value->k AND k NOT IN ('updated_at');
 row_value:=CASE WHEN TG_OP='DELETE' THEN old_value ELSE new_value END;
 IF changed<>'{}'::jsonb THEN INSERT INTO public.hms_audit_log(company_id,entity_type,entity_id,action,performed_by,payload) VALUES ((row_value->>'company_id')::uuid,TG_TABLE_NAME,(row_value->>'id')::uuid,lower(TG_OP),auth.uid(),jsonb_build_object('changes',changed,'summary',TG_TABLE_NAME||' '||lower(TG_OP))); END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.planning_revoke_external(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE e public.planning_external_participants; BEGIN
 SELECT * INTO e FROM public.planning_external_participants WHERE id=_id;
 IF NOT public.planning_external_manager(e.planning_project_id) THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF;
 UPDATE public.planning_external_participants SET status='revoked',deleted_at=now(),deleted_by=auth.uid(),invite_hash=NULL WHERE id=_id;
 INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by) VALUES(e.planning_project_id,'external_revoked','Tilgang avsluttet: '||e.name,auth.uid()); END $function$

CREATE OR REPLACE FUNCTION public.planning_accept_external(_invite_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE e public.planning_external_participants; token text; BEGIN
 SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.invite_hash=encode(extensions.digest(_invite_token,'sha256'),'hex') AND length(_invite_token)>=40 AND ep.invite_expires_at>now() AND ep.status IN ('pending','sent') AND ep.deleted_at IS NULL AND p.deleted_at IS NULL FOR UPDATE OF ep;
 IF e.id IS NULL THEN RAISE EXCEPTION 'Invitasjonen er utløpt eller allerede brukt' USING ERRCODE='42501'; END IF;
 UPDATE public.planning_external_participants SET status='active',accepted_at=now(),invite_hash=NULL WHERE id=e.id;
 token:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.planning_external_sessions(participant_id,token_hash) VALUES(e.id,encode(extensions.digest(token,'sha256'),'hex'));
 INSERT INTO public.planning_activity(planning_project_id,action,summary) VALUES(e.planning_project_id,'external_accepted','Invitasjon godtatt: '||e.name);
 RETURN jsonb_build_object('session_token',token,'project_id',e.planning_project_id); END $function$

CREATE OR REPLACE FUNCTION public.planning_create_external_invite(_project_id uuid, _name text, _email text, _company text, _type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE e public.planning_external_participants; token text; BEGIN
 IF public.planning_external_manager(_project_id) IS NOT TRUE THEN RAISE EXCEPTION 'Du kan ikke invitere til dette prosjektet' USING ERRCODE='42501'; END IF;
 IF _type IS NULL OR _type NOT IN ('customer','supplier') OR _name IS NULL OR length(trim(_name))=0 OR length(trim(_name))>200 OR _company IS NULL OR length(_company)>200 OR _email IS NULL OR length(_email)>254 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Kontroller navn, e-post og type'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_project_id::text,0));
 IF (SELECT count(*) FROM public.planning_activity WHERE planning_project_id=_project_id AND action='external_invited' AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'For mange invitasjoner. Prøv senere'; END IF;
 token:=encode(extensions.gen_random_bytes(32),'hex');
 INSERT INTO public.planning_external_participants(planning_project_id,name,email,company_name,participant_type,created_by,invite_hash,invite_expires_at) VALUES(_project_id,trim(_name),lower(trim(_email)),trim(_company),_type,auth.uid(),encode(extensions.digest(token,'sha256'),'hex'),now()+interval '48 hours') ON CONFLICT(planning_project_id,email) DO UPDATE SET name=EXCLUDED.name,company_name=EXCLUDED.company_name,participant_type=EXCLUDED.participant_type,created_by=EXCLUDED.created_by,status='pending',invite_hash=EXCLUDED.invite_hash,invite_expires_at=EXCLUDED.invite_expires_at,deleted_at=NULL,deleted_by=NULL,accepted_at=NULL RETURNING * INTO e;
 DELETE FROM public.planning_external_sessions WHERE participant_id=e.id;
 INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by) VALUES(_project_id,'external_invited','Ekstern invitert: '||e.name||' · '||e.company_name,auth.uid());
 RETURN jsonb_build_object('id',e.id,'token',token,'name',e.name,'email',e.email,'participant_type',e.participant_type,'project_name',(SELECT name FROM public.planning_projects WHERE id=_project_id)); END $function$

CREATE OR REPLACE FUNCTION public.planning_send_channel_message(_project_id uuid, _channel text, _body text, _external_ids uuid[], _request_id uuid, _reply_to uuid DEFAULT NULL::uuid, _token text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE e public.planning_external_participants; audience jsonb; recipients jsonb; mid uuid; sender_name text; parent public.planning_messages; BEGIN
 IF _project_id IS NULL OR _request_id IS NULL OR _body IS NULL OR length(trim(_body))=0 OR length(_body)>20000 OR _channel IS NULL OR _channel NOT IN ('internal','customer','supplier','all') OR _external_ids IS NULL THEN RAISE EXCEPTION 'Kontroller meldingen og velg mottakere'; END IF;
 IF _token IS NOT NULL THEN e:=public.planning_external_identity(_token); IF e.id IS NULL OR e.planning_project_id IS DISTINCT FROM _project_id OR public.planning_channel_matches(e.participant_type,_channel) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF; sender_name:=e.name;
 ELSE IF public.has_planning_project_access(_project_id) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF; SELECT coalesce(pe.full_name,t.name,'MCS') INTO sender_name FROM (SELECT auth.uid() id) u LEFT JOIN public.user_accounts ua ON ua.auth_user_id=u.id AND ua.is_active=true LEFT JOIN public.people pe ON pe.id=ua.person_id LEFT JOIN public.technicians t ON t.user_id=u.id LIMIT 1; END IF;
 audience:=public.planning_channel_people(_project_id,_channel);
 IF EXISTS(SELECT 1 FROM unnest(_external_ids) i WHERE i IS NULL OR NOT audience @> jsonb_build_array(jsonb_build_object('id',i,'kind','external'))) THEN RAISE EXCEPTION 'Mottaker tilhører ikke samtalen' USING ERRCODE='42501'; END IF;
 IF _reply_to IS NOT NULL THEN SELECT * INTO parent FROM public.planning_messages WHERE id=_reply_to AND planning_project_id=_project_id AND channel=_channel AND deleted_at IS NULL; IF parent.id IS NULL OR (e.id IS NOT NULL AND parent.external_author_id IS DISTINCT FROM e.id AND NOT parent.recipient_snapshot @> jsonb_build_array(jsonb_build_object('id',e.id,'kind','external'))) THEN RAISE EXCEPTION 'Ingen tilgang til meldingen du svarer på' USING ERRCODE='42501'; END IF; END IF;
 SELECT coalesce(jsonb_agg(a),'[]'::jsonb) INTO recipients FROM jsonb_array_elements(audience) a WHERE a->>'kind'='internal' OR (a->>'id')::uuid=ANY(_external_ids);
 SELECT id INTO mid FROM public.planning_messages WHERE client_request_id=_request_id AND planning_project_id=_project_id AND channel=_channel AND ((e.id IS NOT NULL AND external_author_id=[REDACTED] OR (e.id IS NULL AND author_id=[REDACTED] IF mid IS NOT NULL THEN RETURN mid; END IF;
 INSERT INTO public.planning_messages(planning_project_id,channel,body,author_id,external_author_id,author_name,recipient_snapshot,client_request_id,reply_to_id) VALUES(_project_id,_channel,trim(_body),CASE WHEN e.id IS NULL THEN auth.uid() END,e.id,sender_name,recipients,_request_id,_reply_to) RETURNING id INTO mid; RETURN mid; END $function$

CREATE OR REPLACE FUNCTION public.planning_set_external_sharing(_project_id uuid, _kind text, _id uuid, _visibility text, _assignee uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN
 IF public.planning_external_manager(_project_id) IS NOT TRUE OR _visibility IS NULL OR _visibility NOT IN ('internal','customer','supplier','all') THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF;
 IF _assignee IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.planning_external_participants WHERE id=_assignee AND planning_project_id=_project_id AND status='active' AND deleted_at IS NULL AND public.planning_channel_matches(participant_type,_visibility)) THEN RAISE EXCEPTION 'Del oppgaven med ansvarlig sin gruppe først'; END IF;
 IF _kind='file' THEN UPDATE public.planning_files SET shared_visibility=_visibility WHERE id=_id AND planning_project_id=_project_id AND (_visibility='internal' OR (storage_bucket='planning-files' AND split_part(storage_path,'/',1)=_project_id::text));
 ELSIF _kind='task' THEN UPDATE public.planning_tasks SET shared_visibility=_visibility,external_assignee_id=_assignee WHERE id=_id AND planning_project_id=_project_id;
 ELSIF _kind='work_package' THEN UPDATE public.planning_work_packages SET shared_visibility=_visibility WHERE id=_id AND planning_project_id=_project_id;
 ELSE RAISE EXCEPTION 'Ukjent deling'; END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'Kan ikke dele denne posten. Eldre offentlige filer må lastes opp privat først' USING ERRCODE='42501'; END IF;
 INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by,metadata) VALUES(_project_id,'external_sharing_changed','Ekstern synlighet endret',auth.uid(),jsonb_build_object('kind',_kind,'id',_id,'visibility',_visibility,'assignee',_assignee)); END $function$

CREATE OR REPLACE FUNCTION public.planning_external_prepare_login(_participant_id uuid DEFAULT NULL::uuid, _email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 DECLARE e public.planning_external_participants; t text; BEGIN
IF _participant_id IS NOT NULL THEN SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.id=_participant_id AND ep.deleted_at IS NULL AND public.planning_external_mode_for(p.status,p.deleted_at,p.completed_at)<>'none' AND ep.status IN ('active','pending','sent','send_failed');
ELSE SELECT ep.* INTO e FROM public.planning_external_participants ep JOIN public.planning_projects p ON p.id=ep.planning_project_id WHERE ep.email=lower(btrim(_email)) AND ep.deleted_at IS NULL AND public.planning_external_mode_for(p.status,p.deleted_at,p.completed_at)<>'none' AND ep.status='active' ORDER BY ep.accepted_at DESC LIMIT 1; END IF;
IF e.id IS NULL THEN RETURN NULL; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(e.external_person_id::text,42));
IF EXISTS(SELECT 1 FROM public.planning_external_login_links l JOIN public.planning_external_participants ep ON ep.id=l.participant_id WHERE ep.external_person_id=e.external_person_id AND l.created_at>now()-interval '2 minutes') THEN RETURN NULL; END IF;
IF (SELECT count(*) FROM public.planning_external_login_links l JOIN public.planning_external_participants ep ON ep.id=l.participant_id WHERE ep.external_person_id=e.external_person_id AND l.created_at>now()-interval '1 hour')>=5 THEN RETURN NULL; END IF;
t:=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.planning_external_login_links(participant_id,token_hash) VALUES(e.id,encode(extensions.digest(t,'sha256'),'hex'));
RETURN jsonb_build_object('link_id',(SELECT id FROM public.planning_external_login_links WHERE token_hash=[REDACTED]'sha256'),'hex')),'id',e.id,'token',t,'name',e.name,'email',e.email,'participant_type',e.participant_type,'project_name',(SELECT name FROM public.planning_projects WHERE id=e.planning_project_id),'project_id',e.planning_project_id); END $function$

CREATE OR REPLACE FUNCTION public.validate_planning_task_assignee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE prim record;
BEGIN
  IF NEW.assignee_person_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.assignee_person_id IS NOT DISTINCT FROM OLD.assignee_person_id
     AND NEW.company_id IS NOT DISTINCT FROM OLD.company_id
     AND NEW.department_id IS NOT DISTINCT FROM OLD.department_id THEN
    RETURN NEW;
  END IF;
  IF NEW.company_id IS NULL THEN
    SELECT e.company_id, e.department_id INTO prim FROM public.employment_profiles e
     WHERE e.person_id = NEW.assignee_person_id AND e.archived_at IS NULL
       AND coalesce(e.relationship_type,'employee') = 'employee'
     ORDER BY e.is_primary DESC NULLS LAST, e.created_at LIMIT 1;
    IF prim.company_id IS NULL THEN
      RAISE EXCEPTION 'Personen har ingen aktiv ansettelse' USING ERRCODE = '23514';
    END IF;
    NEW.company_id := prim.company_id;
    NEW.department_id := coalesce(NEW.department_id, prim.department_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.employment_profiles e
                  WHERE e.person_id = NEW.assignee_person_id AND e.archived_at IS NULL
                    AND coalesce(e.relationship_type,'employee') = 'employee'
                    AND e.company_id = NEW.company_id
                    AND (NEW.department_id IS NULL OR e.department_id = NEW.department_id)) THEN
    RAISE EXCEPTION 'Personen er ikke ansatt i valgt selskap/avdeling' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.planning_projects_external_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE old_mode text; new_mode text; n int;
BEGIN
  old_mode := public.planning_external_mode_for(OLD.status, OLD.deleted_at, OLD.completed_at);
  new_mode := public.planning_external_mode_for(NEW.status, NEW.deleted_at, NEW.completed_at);
  IF new_mode='none' AND old_mode<>'none' THEN
    UPDATE public.planning_external_sessions s SET expires_at=least(s.expires_at,now()) FROM public.planning_external_participants e WHERE e.id=s.participant_id AND e.planning_project_id=NEW.id AND s.expires_at>now();
    UPDATE public.planning_external_login_links l SET used_at=coalesce(l.used_at,now()) FROM public.planning_external_participants e WHERE e.id=l.participant_id AND e.planning_project_id=NEW.id AND l.used_at IS NULL;
    INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by,metadata) VALUES(NEW.id,'external_access_closed','Ekstern tilgang avsluttet fordi prosjektet ble stengt',auth.uid(),jsonb_build_object('status',NEW.status,'deleted',NEW.deleted_at IS NOT NULL));
  ELSIF old_mode='none' AND new_mode<>'none' THEN
    UPDATE public.planning_external_participants SET status='paused' WHERE planning_project_id=NEW.id AND status='active' AND deleted_at IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n>0 THEN INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by,metadata) VALUES(NEW.id,'external_access_paused',n||' ekstern(e) satt på pause etter gjenåpning',auth.uid(),'{}'::jsonb); END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.planning_external_resume(_participant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pid uuid;
BEGIN
  SELECT planning_project_id INTO pid FROM public.planning_external_participants WHERE id=_participant_id AND status='paused' AND deleted_at IS NULL;
  IF pid IS NULL OR public.planning_external_manager(pid) IS NOT TRUE THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE='42501'; END IF;
  IF public.planning_project_external_mode(pid)='none' THEN RAISE EXCEPTION 'Prosjektet er stengt for eksterne'; END IF;
  UPDATE public.planning_external_participants SET status='active' WHERE id=_participant_id;
  INSERT INTO public.planning_activity(planning_project_id,action,summary,performed_by,metadata) VALUES(pid,'external_access_resumed','Ekstern tilgang aktivert igjen',auth.uid(),jsonb_build_object('participant_id',_participant_id));
END $function$

CREATE OR REPLACE FUNCTION public.attach_competence_document(_actor uuid, _competence_id uuid, _path text, _file_name text, _file_size bigint, _client_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _company uuid; _doc uuid;
BEGIN
  SELECT id INTO _doc FROM documents WHERE client_request_id = _client_request_id;
  IF _doc IS NOT NULL THEN RETURN _doc; END IF;
  _company := public.competence_document_can_manage(_actor, _competence_id);
  IF _company IS NULL THEN RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501'; END IF;
  IF _path NOT LIKE 'compliance/' || _company || '/' || _competence_id || '/%' THEN
    RAISE EXCEPTION 'invalid path' USING ERRCODE = '22023';
  END IF;
  INSERT INTO documents(entity_type, entity_id, company_id, category, source_type, storage_bucket,
    file_path, file_name, file_size, mime_type, public_url, uploaded_by, client_request_id)
  VALUES ('compliance_competence', _competence_id, _company, 'kompetanse', 'api_upload', 'compliance-documents',
    _path, _file_name, _file_size, 'application/pdf', NULL, _actor, _client_request_id)
  RETURNING id INTO _doc;
  UPDATE compliance_competences SET document_id = _doc WHERE id = _competence_id;
  INSERT INTO activity_log(entity_type, entity_id, action, performed_by, description, metadata)
  VALUES ('compliance_competence', _competence_id, 'document_attached', _actor,
    'Dokumentasjon lastet opp: ' || _file_name,
    jsonb_build_object('summary', 'Dokumentasjon lastet opp: ' || _file_name, 'document_id', _doc));
  RETURN _doc;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_m365_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE ev uuid; tech uuid; op text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.start_at IS NOT DISTINCT FROM OLD.start_at AND NEW.end_at IS NOT DISTINCT FROM OLD.end_at THEN RETURN NEW; END IF;
 ev:=CASE WHEN TG_OP='DELETE' THEN OLD.event_id ELSE NEW.event_id END; tech:=CASE WHEN TG_OP='DELETE' THEN OLD.technician_id ELSE NEW.technician_id END;
 op:=CASE TG_OP WHEN 'DELETE' THEN 'delete' WHEN 'INSERT' THEN 'create' ELSE 'update' END;
 INSERT INTO public.m365_communication_queue(event_id,technician_id,operation) VALUES(ev,tech,op)
 ON CONFLICT(event_id,technician_id) DO UPDATE SET operation=EXCLUDED.operation,status=CASE WHEN public.m365_communication_queue.status='processing' THEN 'processing' ELSE 'pending' END, revision=public.m365_communication_queue.revision+1,updated_at=now();
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END; $function$

CREATE OR REPLACE FUNCTION public.save_permission_override_changes(_account uuid, _company uuid, _changes jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE item jsonb; current_row public.user_permission_overrides_v2%ROWTYPE; login_id uuid; desired text;
BEGIN
 IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(_changes) <> 'array' OR jsonb_array_length(_changes)>300 THEN RAISE EXCEPTION 'Invalid changes'; END IF;
 SELECT auth_user_id INTO login_id FROM public.user_accounts WHERE id=_account FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Account not found'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_changes) x GROUP BY x->>'permission_key' HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate permission keys'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(_changes) LOOP
  desired := item->>'mode';
  IF coalesce(item->>'permission_key','')='' OR length(item->>'permission_key')>200 OR (desired IS NOT NULL AND desired NOT IN ('allow','deny')) THEN RAISE EXCEPTION 'Invalid permission'; END IF;
  SELECT * INTO current_row FROM public.user_permission_overrides_v2 WHERE user_account_id=_account AND permission_key=[REDACTED]'permission_key' FOR UPDATE;
  IF FOUND THEN
   IF current_row.scope_company_id IS DISTINCT FROM _company OR current_row.scope_department_id IS NOT NULL THEN RAISE EXCEPTION 'Permission exists in a different scope; edit original scope'; END IF;
   IF desired IS NOT NULL AND current_row.mode=desired THEN CONTINUE; END IF;
   IF item->'expected'->>'mode' IS DISTINCT FROM current_row.mode THEN RAISE EXCEPTION 'Permissions changed; reload before saving'; END IF;
  ELSIF item->'expected' IS NOT NULL AND item->'expected'<>'null'::jsonb AND desired IS NOT NULL THEN RAISE EXCEPTION 'Permissions changed; reload before saving';
  END IF;
  IF desired IS NULL THEN
   DELETE FROM public.user_permission_overrides_v2 WHERE user_account_id=_account AND permission_key=[REDACTED]'permission_key' AND scope_company_id IS NOT DISTINCT FROM _company;
  ELSE
   INSERT INTO public.user_permission_overrides_v2(user_account_id,permission_key,mode,scope_company_id) VALUES(_account,item->>'permission_key',desired,_company)
   ON CONFLICT(user_account_id,permission_key) DO UPDATE SET mode=excluded.mode;
  END IF;
  DELETE FROM public.user_permission_overrides WHERE user_id=login_id AND permission_key=[REDACTED]'permission_key';
  IF _company IS NULL AND desired IS NOT NULL THEN
   INSERT INTO public.user_permission_overrides(user_id,permission_key,allowed) VALUES(login_id,item->>'permission_key',desired='allow') ON CONFLICT(user_id,permission_key) DO UPDATE SET allowed=excluded.allowed;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.notify_new_order_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_admin uuid; v_title text; v_msg text; v_link text; v_who text; v_summary_text text;
BEGIN
  IF NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
  BEGIN
    v_who := COALESCE(NULLIF(NEW.submitter_name, ''), NULLIF(NEW.submitter_email, ''), 'Ukjent avsender');
    IF NEW.summary IS NOT NULL AND jsonb_typeof(NEW.summary) = 'object' THEN
      v_summary_text := COALESCE(NULLIF(NEW.summary ->> 'oppdragstittel', ''), NULLIF(NEW.summary ->> 'firmanavn', ''),
        NULLIF(NEW.summary ->> 'kundenavn', ''), NULLIF(NEW.summary ->> 'bestiller_navn', ''));
    ELSIF NEW.summary IS NOT NULL AND jsonb_typeof(NEW.summary) IN ('string', 'number', 'boolean') THEN
      v_summary_text := NULLIF(btrim(NEW.summary #>> '{}'), '');
    END IF;
    v_title := COALESCE(v_summary_text, 'Ny servicebestilling fra ' || v_who);
    v_msg := 'Ny servicebestilling: ' || v_who || COALESCE(' · ' || NEW.priority, '');
    v_link := '/orders/' || NEW.id::text;

    -- Only designated intake recipients for this company (superadmin fallback when empty)
    FOR v_admin IN SELECT DISTINCT r FROM public.order_intake_recipients(NEW.company_id) r WHERE r IS NOT NULL LOOP
      BEGIN
        IF NOT EXISTS (SELECT 1 FROM public.notifications n WHERE n.user_id = v_admin AND n.type = 'new_order' AND n.entity_id = NEW.id) THEN
          INSERT INTO public.notifications (user_id, type, title, message, link_url, priority, entity_type, entity_id, company_id)
          VALUES (v_admin, 'new_order', v_title, v_msg, v_link, 'important', 'order_submission', NEW.id, NEW.company_id);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        BEGIN
          INSERT INTO public.order_form_activity_log (submission_id, event_type, payload)
          VALUES (NEW.id, 'notification_failed', jsonb_build_object('notification_type', 'intake_notification',
            'admin_user_id', v_admin, 'error', SQLERRM, 'sqlstate', SQLSTATE, 'submission_id', NEW.id));
        EXCEPTION WHEN OTHERS THEN NULL; END;
      END;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.order_form_activity_log (submission_id, event_type, payload)
      VALUES (NEW.id, 'notification_failed', jsonb_build_object('notification_type', 'new_order_submission_trigger',
        'error', SQLERRM, 'sqlstate', SQLSTATE, 'submission_id', NEW.id));
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_order_intake_member(_company_id uuid, _user_account_id uuid, _admin boolean, _notify boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auth uuid; v_is_sa boolean; v_before_admin boolean; v_before_notify boolean; v_notify boolean;
BEGIN
  IF NOT public.is_global_superadmin(auth.uid()) THEN RAISE EXCEPTION 'Ingen tilgang' USING ERRCODE = '42501'; END IF;
  SELECT auth_user_id INTO v_auth FROM public.user_accounts WHERE id = _user_account_id AND is_active;
  IF v_auth IS NULL THEN RAISE EXCEPTION 'Ukjent eller inaktiv konto'; END IF;
  v_is_sa := public.is_global_superadmin(v_auth);
  IF _admin AND NOT v_is_sa AND NOT EXISTS (SELECT 1 FROM public.user_memberships WHERE user_id = v_auth AND company_id = _company_id AND is_active) THEN
    RAISE EXCEPTION 'Personen er ikke aktivt medlem i selskapet';
  END IF;
  v_before_admin := public.has_order_intake(_user_account_id, _company_id);
  v_before_notify := COALESCE((SELECT is_active FROM public.order_notification_subscriptions WHERE user_account_id = _user_account_id AND company_id = _company_id), false);
  v_notify := _notify AND (_admin OR v_is_sa);

  IF NOT v_is_sa THEN
    IF _admin THEN
      INSERT INTO public.user_permission_overrides_v2 (user_account_id, permission_key, scope_company_id, mode)
      SELECT _user_account_id, 'orders.intake', _company_id, 'allow'
      WHERE NOT EXISTS (SELECT 1 FROM public.user_permission_overrides_v2 WHERE user_account_id = _user_account_id AND permission_key = 'orders.intake' AND scope_company_id = _company_id);
    ELSE
      DELETE FROM public.user_permission_overrides_v2 WHERE user_account_id = _user_account_id AND permission_key = 'orders.intake' AND scope_company_id = _company_id;
    END IF;
  END IF;

  INSERT INTO public.order_notification_subscriptions (user_account_id, company_id, is_active, updated_by, updated_at)
  VALUES (_user_account_id, _company_id, v_notify, auth.uid(), now())
  ON CONFLICT (user_account_id, company_id) DO UPDATE SET is_active = EXCLUDED.is_active, updated_by = EXCLUDED.updated_by, updated_at = now();

  IF v_before_admin IS DISTINCT FROM (_admin OR v_is_sa) OR v_before_notify IS DISTINCT FROM v_notify THEN
    INSERT INTO public.access_audit_log (user_id, company_id, module, level, action, details, performed_by)
    VALUES (v_auth, _company_id, 'orders.intake', CASE WHEN _admin OR v_is_sa THEN 'admin' ELSE 'none' END, 'order_intake_changed',
      jsonb_build_object('user_account_id', _user_account_id,
        'before', jsonb_build_object('admin', v_before_admin, 'notify', v_before_notify),
        'after', jsonb_build_object('admin', _admin OR v_is_sa, 'notify', v_notify)), auth.uid());
  END IF;
END $function$
